  'Once the payment is approved, the certificate is also sent to this number on WhatsApp.' => 'Sobald die Zahlung genehmigt ist, wird das Zertifikat auch auf WhatsApp an diese Nummer gesendet.',
  'Any amount you like' => 'Jeder gewünschte Betrag',
