  'Your donation is confirmed automatically once the payment goes through. Thank you so much for your support 🤲' => 'Ihre Spende wird automatisch bestätigt, sobald die Zahlung erfolgt ist. Vielen Dank für eure Unterstützung 🤲',
  'Your payment page is ready: %s' => 'Ihre Zahlungsseite ist fertig: %s',
