  'Messages are downloaded with time and author (contact, assistant, agent, automatic); the receipt check result is included.' => 'Nachrichten werden mit Uhrzeit und Autor (Kontakt, Assistent, Agent, automatisch) heruntergeladen; Das Ergebnis der Eingangskontrolle ist enthalten.',
