  'The copy on the Evolution server will not be imported again; the assistant starts fresh in this chat. You may want to export the chat first.' => 'Die Kopie auf dem Evolution-Server wird nicht erneut importiert; Der Assistent beginnt in diesem Chat neu. Möglicherweise möchten Sie den Chat zuerst exportieren.',
