  'No WhatsApp, email or SMS is sent to these contacts and the assistant does not talk to them. The assistant adds anyone who says "don\'t message me". Removing someone from the list turns everything back on.' => 'An diese Kontakte wird keine WhatsApp, E-Mail oder SMS gesendet und der Assistent spricht nicht mit ihnen. Der Assistent fügt jeden hinzu, der sagt: „Schreib mir keine Nachricht“. Durch das Entfernen einer Person aus der Liste wird alles wieder aktiviert.',
