  'Not checked' => 'Nicht überprüft',
  'We received your receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Wir haben Ihre Quittung erhalten, vielen Dank 🌱 Wir werden uns so schnell wie möglich bezüglich Ihrer Zahlung bei Ihnen melden.',
  'We received your receipt, thank you 🌱 Your donation is confirmed.' => 'Wir haben Ihre Quittung erhalten, vielen Dank 🌱 Ihre Spende ist bestätigt.',
  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Wir haben diese Quittung bereits erhalten, vielen Dank 🌱 Wir werden uns schnellstmöglich bezüglich Ihrer Zahlung bei Ihnen melden.',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => 'Diese Quittung scheint bereits zuvor in unser System hochgeladen worden zu sein. Die gleiche Quittung kann nicht für eine zweite Spende verwendet werden. Wenn Sie eine andere Zahlung getätigt haben, senden Sie bitte diese Quittung; Unser Team wird dies auch überprüfen.',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => 'Wir haben Ihre Quittung erhalten. Der darauf angegebene Betrag (%1$s) scheint nicht mit Ihrem Spendenbetrag (%2$s) übereinzustimmen. Könnten Sie es überprüfen? Wenn Sie eine andere Zahlung vorgenommen haben, können Sie hier schreiben; Unser Team wird auch einen Blick darauf werfen.',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => 'Wir haben Ihre Quittung erhalten, aber der darauf angegebene Empfänger scheint nicht unser Verein zu sein. Spenden erfolgen ausschließlich auf unser Konto im Namen von „%s“. Könnten Sie das überprüfen? Unser Team wird auch einen Blick darauf werfen.',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => 'Wir haben Ihre Quittung erhalten, aber der darauf angegebene Empfänger scheint nicht mit unserem Konto übereinzustimmen. Könnten Sie das überprüfen? Unser Team wird auch einen Blick darauf werfen.',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => 'Die von Ihnen gesendete Datei sieht nicht wie ein Zahlungsbeleg aus. Wenn Sie bezahlt haben, können Sie hier die Quittung oder einen Screenshot des Zahlungsbildschirms senden.',
