  '+ New report' => '+ Neuer Bericht',
  'The recipient\'s number comes from Users › Profile › WhatsApp number; permissions from Users › Roles and access (receive reports, view overall report, manage reports). Reports go out at the chosen time; without a server scheduler they are sent on the next site visit or chat panel use.' => 'Die Nummer des Empfängers stammt aus Benutzer › Profil › WhatsApp-Nummer; Berechtigungen von Benutzern › Rollen und Zugriff (Berichte empfangen, Gesamtbericht anzeigen, Berichte verwalten). Berichte werden zum gewählten Zeitpunkt verschickt; Ohne einen Server-Scheduler werden sie beim nächsten Website-Besuch oder bei der nächsten Nutzung des Chat-Panels gesendet.',
  'Invalid phone number.' => 'Ungültige Telefonnummer.',
  'First add a WhatsApp connection under Settings › Connections.' => 'Fügen Sie zunächst unter Einstellungen › Verbindungen eine WhatsApp-Verbindung hinzu.',
