  'File is too large (max %s).' => 'Die Datei ist zu groß (max.%s).',
  'This file type cannot be sent.' => 'Dieser Dateityp kann nicht gesendet werden.',
  'File could not be uploaded.' => 'Datei konnte nicht hochgeladen werden.',
  'This message cannot be resent.' => 'Diese Nachricht kann nicht erneut gesendet werden.',
  'Can\'t react to this message.' => 'Auf diese Nachricht kann nicht reagiert werden.',
  'You can only delete your own notes.' => 'Sie können nur Ihre eigenen Notizen löschen.',
  'Reply text cannot be empty.' => 'Der Antworttext darf nicht leer sein.',
  'Connection not found. Save the settings first.' => 'Verbindung nicht gefunden. Speichern Sie zunächst die Einstellungen.',
  'The message was only image code; it was not sent.' => 'Die Nachricht bestand nur aus Bildcode; es wurde nicht gesendet.',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => 'Dieser Kontakt steht auf der Sperrliste. Es werden keine Nachrichten gesendet. Entfernen Sie sie aus der Sperrliste, um erneut schreiben zu können.',
  'Message could not be saved.' => 'Die Nachricht konnte nicht gespeichert werden.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Dieser Kontakt schreibt von einer versteckten WhatsApp-Nummer (@lid) und Evolution API (Version %s) konnte nicht an diese Adresse senden. Aktualisieren Sie den Evolution API-Server auf 2.3 oder höher; Wenn die tatsächliche Nummer des Kontakts eintrifft, sendet das Plugin dorthin.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Dieser Kontakt schreibt von einer versteckten WhatsApp-Nummer (@lid) und Evolution API konnte nicht an diese Adresse senden. Aktualisieren Sie den Evolution API-Server auf 2.3 oder höher; Wenn die tatsächliche Nummer des Kontakts eintrifft, sendet das Plugin dorthin.',
  'No WhatsApp connection.' => 'Keine WhatsApp-Verbindung.',
  'Connected ✓' => 'Verbunden ✓',
  'Not connected (state: %s). Connect with QR.' => 'Nicht verbunden (Status: %s). Verbinden Sie sich mit QR.',
  'Webhook points to this site ✓' => 'Webhook verweist auf diese Site ✓',
  'Evolution API version: %s' => 'Evolution-API-Version: %s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(alt: Antworten auf Kontakte mit versteckten Nummern (@lid) schlagen möglicherweise fehl, aktualisieren Sie auf 2.3 oder höher)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'Der Webhook verweist nicht auf diese Site. Klicken Sie auf „Webhook einrichten“.',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Webhook eingerichtet ✓ Eingehende Nachrichten kommen nun hier an.',
  'Importing recent chats, this may take a while…' => 'Aktuelle Chats werden importiert. Dies kann eine Weile dauern.',
  'Messages stored in Evolution: %s' => 'In Evolution gespeicherte Nachrichten: %s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'Evolution speichert keine Nachrichten, daher können ältere Nachrichten nicht geladen werden. Setzen Sie auf dem Evolution-Server DATABASE_SAVE_DATA_NEW_MESSAGE und DATABASE_SAVE_DATA_HISTORIC auf true; Lassen Sie für ältere Konversationen „Vollständigen Verlauf synchronisieren“ in den Instanzeinstellungen aktiviert, wenn Sie die Leitung erneut mit QR verbinden.',
  '%1$s chats, %2$s messages imported ✓' => '%1$s-Chats, %2$s-Nachrichten importiert ✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'Scannen Sie diesen Code über WhatsApp › Verknüpfte Geräte › Gerät verknüpfen.',
  'Pairing code:' => 'Pairing-Code:',
  'This line is already connected ✓' => 'Diese Leitung ist bereits verbunden ✓',
  'Save the settings first.' => 'Speichern Sie zunächst die Einstellungen.',
  'Error:' => 'Fehler:',
  'Delete this connection? Chat history is kept.' => 'Diese Verbindung löschen? Der Chatverlauf wird gespeichert.',
  'Asking the AI…' => 'Die KI fragen...',
  'Working ✓ (%2$s ms): %1$s' => 'Funktioniert ✓ (%2$s ms): %1$s',
  'Save the key and model first.' => 'Speichern Sie zunächst den Schlüssel und das Modell.',
  'Connections' => 'Verbindungen',
  'Auto replies' => 'Automatische Antworten',
  'AI and assistant' => 'KI und Assistent',
  'System check' => 'Systemprüfung',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'Verbinden Sie Ihre WhatsApp-Leitung, verwalten Sie automatische Antworten und Labels.',
  'Open chats' => 'Offene Chats',
  'Settings saved.' => 'Einstellungen gespeichert.',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'Verbindungen und Einstellungen, die das Callcenter benötigt. Der gespeicherte Status wird angezeigt. Verwenden Sie die „Test“-Schaltflächen auf jeder Registerkarte für eine Live-Überprüfung. Dieselben Prüfungen werden auch bei den anderen Plugins auf dem Systemprüfungsbildschirm des Themes angezeigt.',
  'WhatsApp lines' => 'WhatsApp-Zeilen',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'Nachrichten werden über die Evolution API gesendet und empfangen. WhatsApp-Verbindungen werden in Flux Mail verwaltet; Wählen Sie hier aus, welches Sie verwenden möchten. Die URL und der API-Schlüssel bleiben dort, sodass Sie sie hier nicht aktualisieren müssen, wenn sie sich ändern.',
  'Communication › Connections' => 'Kommunikation › Verbindungen',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'Nachrichten werden über die Evolution API gesendet und empfangen. Wenn in Flux Certificates ein Evolution-Anbieter eingerichtet ist, können Sie dieselbe Verbindung auswählen; Die URL und der API-Schlüssel bleiben dort.',
  'Add line' => 'Zeile hinzufügen',
  'Setup steps' => 'Einrichtungsschritte',
  'Add the line and save.' => 'Fügen Sie die Zeile hinzu und speichern Sie.',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => 'Verwenden Sie „Verbindung testen“, um festzustellen, ob Evolution erreichbar ist. Wenn die Leitung nicht verknüpft ist, wählen Sie „Mit QR verbinden“ und scannen Sie sie vom Telefon aus.',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => 'Klicken Sie auf „Webhook einrichten“. Eingehende Nachrichten sowie Nachrichten, die vom Telefon und von Flux-Zertifikaten gesendet werden, werden dann hier live angezeigt.',
  'Optionally bring in past messages with "Import recent chats".' => 'Optional können Sie mit „Letzte Chats importieren“ frühere Nachrichten einbinden.',
  'connected' => 'verbunden',
  'connecting' => 'verbinden',
  'not connected' => 'nicht verbunden',
  'not on server' => 'nicht auf dem Server',
  'unreachable' => 'unerreichbar',
  'Flux Mail connection: %s' => 'Flux Mail-Verbindung: %s',
  'Flux Mail connection #%d (not found or disabled)' => 'Flux Mail-Verbindung #%d(nicht gefunden oder deaktiviert)',
  'Use Flux Certificates provider: %s' => 'Verwenden Sie den Flux-Zertifikatsanbieter: %s',
  'Enter separate Evolution API details' => 'Geben Sie separate Evolution-API-Details ein',
  'Line name (e.g. Main line)' => 'Linienname (z. B. Hauptlinie)',
  'Connection details' => 'Verbindungsdetails',
  'API URL' => 'API-URL',
  'Instance name' => 'Instanzname',
  'API key (apikey)' => 'API-Schlüssel (apikey)',
  '•••••••• (saved; type to change)' => '•••••••• (gespeichert; zum Ändern eingeben)',
  'Webhook URL' => 'Webhook-URL',
  'Regenerate secret key' => 'Geheimen Schlüssel neu generieren',
  'Last webhook: %s' => 'Letzter Webhook: %s',
  'No webhook received yet.' => 'Noch kein Webhook empfangen.',
  'Test connection' => 'Testverbindung',
  'Connect with QR' => 'Verbinden Sie sich mit QR',
  'QR, status and accounts: Communication › Connections' => 'QR, Status und Konten: Kommunikation › Verbindungen',
  'Set up webhook' => 'Webhook einrichten',
  'Import recent chats' => 'Aktuelle Chats importieren',
  'The webhook URL and test buttons appear after saving.' => 'Nach dem Speichern werden die Webhook-URL und die Testschaltflächen angezeigt.',
  'Appearance' => 'Aussehen',
  'Panel title' => 'Titel des Panels',
  'Site name if empty. The {brand} variable uses this too.' => 'Site-Name, falls leer. Auch die Variable {brand} verwendet dies.',
  'Accent color' => 'Akzentfarbe',
  'Behavior' => 'Verhalten',
  'Send read receipts (blue ticks) when a chat is opened' => 'Senden Sie Lesebestätigungen (blaue Häkchen), wenn ein Chat geöffnet wird',
  'Prefix messages with the agent\'s name (*Name:*)' => 'Stellen Sie den Nachrichten den Namen des Agenten (*Name:*) voran.',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'Agenten sehen nur die ihnen zugewiesenen Chats und die nicht zugewiesenen Chats (Administratoren sehen alle)',
  'Also show WhatsApp group messages' => 'Zeigen Sie auch WhatsApp-Gruppennachrichten an',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => 'Neue Benutzeroberfläche (experimentell): Die Chats-Seite wird mit demselben Bildschirm wie die Desktop- und Mobil-App geöffnet',
  'Live update interval (sec)' => 'Live-Update-Intervall (Sek.)',
  'Agents' => 'Agenten',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'Weisen Sie einem Benutzer die Rolle %s zu. Sie sehen nur den Chat-Bildschirm und können die Einstellungen nicht öffnen. Administratoren haben immer Zugriff.',
  'Add new user' => 'Neuen Benutzer hinzufügen',
  'Data' => 'Daten',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'Löschen Sie auch alle Chats, Nachrichten und Mediendateien, wenn das Plugin gelöscht wird',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'Mediendateien werden in wp-content/uploads/flx-chat aufbewahrt und sind für den Zugriff von außen gesperrt. Sie werden mit den Uploads verschoben, wenn die Website migriert wird.',
  'Mon' => 'Mo',
  'Tue' => 'Di',
  'Wed' => 'Mi',
  'Thu' => 'Do',
  'Fri' => 'Fr',
  'Sat' => 'Sa',
  'Sun' => 'Sonne',
  'Welcome message' => 'Willkommensnachricht',
  'Send automatically to people who write to us for the first time' => 'Automatisch an Personen senden, die uns zum ersten Mal schreiben',
  'Away message' => 'Abwesenheitsnachricht',
  'Auto reply to messages received outside business hours' => 'Automatische Antwort auf Nachrichten, die außerhalb der Geschäftszeiten eingehen',
  'Business days' => 'Werktage',
  'Start' => 'Starten',
  'End' => 'Ende',
  'At most once per contact every (hours)' => 'Höchstens einmal pro Kontakt alle (Stunden)',
  'Timezone: %1$s. Now: %2$s.' => 'Zeitzone: %1$s. Jetzt: %2$s.',
  'within business hours' => 'innerhalb der Geschäftszeiten',
  'outside business hours' => 'außerhalb der Geschäftszeiten',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => 'In den Texten können die Variablen {first_name}, {name}, {brand}, {site}, {date} verwendet werden.',
  'Chat labels' => 'Chat-Labels',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'Kennzeichnen Sie Chats und filtern Sie die Liste (z. B. Spende, Beschwerde, Nachverfolgung).',
  'Add label' => 'Etikett hinzufügen',
  'Label name' => 'Labelname',
  'Creating records from chats' => 'Erstellen von Aufzeichnungen aus Chats',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'Schaltflächen im Chat-Header erstellen einen Spendendatensatz (Flux Donate) und ein Zertifikat (Flux Certificates) und eine eingehende Quittung wird einem Datensatz zugeordnet. Wenn ein Plugin nicht installiert ist, ist seine Schaltfläche ausgeblendet.',
  'Agents can create donation records and match receipts' => 'Agenten können Spendenaufzeichnungen erstellen und Belege abgleichen',
  'Agents can create and send certificates' => 'Agenten können Zertifikate erstellen und versenden',
  'Show quick reply bubbles above the message box' => 'Über dem Nachrichtenfeld werden Schnellantwortblasen angezeigt',
  'Donation messages' => 'Spendennachrichten',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'Fertigtexte, die beim Erstellen eines Datensatzes an die Person gesendet werden (vor dem Senden bearbeitbar). Wenn es leer bleibt, wird der Standardtext verwendet.',
  'Awaiting payment (promised transfer)' => 'Warten auf Zahlung (versprochene Überweisung)',
  'Donation received' => 'Spende erhalten',
  'Receipt confirmed' => 'Empfang bestätigt',
  'Bank details ({bank})' => 'Bankverbindung ({bank})',
  'Recipient name, bank, IBAN' => 'Empfängername, Bank, IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => 'Wenn leer, wird das Konto in WooCommerce › Zahlungen › Banküberweisung verwendet.',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variablen: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.',
  'AI connection' => 'KI-Verbindung',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'Schlüssel, Prompt-Caching, Ausgabenlimits und Nutzungsprotokolle stammen vom Flux AI & MCP-Plugin; Alle KI-Anfragen des Callcenters durchlaufen es. Die Modellauswahl bleibt hier; Wenn ein Feld leer ist, wird das für dieses Plugin in Flux AI ausgewählte Modell (oder die Standardeinstellung) verwendet.',
  'Open Flux AI settings' => 'Öffnen Sie die Flux AI-Einstellungen',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'AI benötigt das Flux AI & MCP Plugin. Installieren und aktivieren Sie es und geben Sie dann den OpenRouter- und/oder Anthropic-Schlüssel in Flux AI & MCP › Einstellungen ein. Bis dahin sind Vorschläge, der Assistent, das Lesen von Quittungen, Sprachnachrichten und Zusammenfassungen deaktiviert.',
  'Creativity (0–1)' => 'Kreativität (0–1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => 'Niedrigere Werte führen zu konsistenteren Antworten, höhere Werte zu freizügigeren. 0,4 empfohlen.',
  'Model (for suggestions)' => 'Modell (für Vorschläge)',
  'Assistant model (optional)' => 'Assistentenmodell (optional)',
  'Model above' => 'Modell oben',
  'Only models that support tools are listed.' => 'Es werden nur Modelle aufgeführt, die Tools unterstützen.',
  'Receipt reading model (optional)' => 'Quittungslesemodell (optional)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => 'Wenn das ausgewählte Modell keine Bilder lesen kann, wird automatisch ein günstiges Vision-Modell verwendet.',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => 'Diesen Monat (%1$s): %2$s-Anfragen, %3$s-Tokens, etwa $%4$s.',
  'Reply suggestions' => 'Antwortvorschläge',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'Über dem Nachrichtenfeld wird die nächste Nachricht aus der Konversation vorgeschlagen. Der Agent klickt auf „Senden“ oder übernimmt es mit „Bearbeiten“ in die Box. Ein Vorschlag wird niemals einzeln gesendet.',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => 'Bereiten Sie automatisch einen Vorschlag vor, wenn die letzte Nachricht von der Person kam (falls deaktiviert, fragen Sie mit der ✨-Taste nach).',
  'Organization info and tone' => 'Informationen und Ton der Organisation',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => 'Z.B. Unser Verein pflanzt Setzlinge in Istanbul. Die Pflanzung erfolgt jedes Jahr zwischen November und März. Die Bescheinigung wird nach der Spende per WhatsApp verschickt. Verwenden Sie einen warmen, aber formellen Ton.',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => 'Vorschläge und der Assistent nutzen dies. Spendenarten, Preise, Bankdaten und Schnellantworten werden automatisch hinzugefügt.',
  'Suggestion provider' => 'Vorschlagsanbieter',
  'Donation assistant (automatic replies)' => 'Spendenassistent (automatische Antworten)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'Wenn aktiviert, antwortet der Assistent selbst: Er begrüßt, fragt nach dem Namen, um ihn anzusprechen, sendet Spendenoptionen und Preise, sammelt optional E-Mails und „in wessen Namen“ und bittet nach jeder Änderung um eine Bestätigung. Nach der Bestätigung öffnet es in Flux Donate einen Datensatz „Warten auf Zahlung“ und sendet den Spendenlink, den Empfänger, die IBAN und die Referenz als separate Nachrichten. Wenn das Thema Spenden hinterlässt, übergibt es den Chat an das Team.',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'Das Flux Donate-Plugin ist nicht aktiv; Der Assistent kann keine Spendendatensätze erstellen.',
  'Instructions, documents, AI chats and test chat' => 'Anleitungen, Dokumente, KI-Chats und Testchat',
  'Turn on the donation assistant (untick to turn it off everywhere)' => 'Schalten Sie den Spendenassistenten ein (entfernen Sie das Häkchen, um ihn überall auszuschalten)',
  'Which chats should it reply to' => 'Auf welche Chats soll geantwortet werden?',
  'In all chats (recommended)' => 'In allen Chats (empfohlen)',
  'In chats not assigned to an agent' => 'In Chats, die keinem Agenten zugewiesen sind',
  'Only outside working hours' => 'Nur außerhalb der Arbeitszeit',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'Wenn ein Agent in einem Chat schreibt (über das Panel oder das Telefon), bleibt der Assistent dort für die unten angegebene Zeit still. Verwenden Sie die Assistentenschaltfläche im Chat-Header, um es pro Chat ein- oder auszuschalten.',
  'Test mode: reply only to the numbers below' => 'Testmodus: Antworten Sie nur auf die untenstehenden Nummern',
  'Test numbers' => 'Testzahlen',
  'Separate with commas or new lines. Not used when test mode is off.' => 'Trennen Sie durch Kommas oder neue Zeilen. Wird nicht verwendet, wenn der Testmodus ausgeschaltet ist.',
  'Quiet after an agent writes (hours)' => 'Ruhe, nachdem ein Agent schreibt (Stunden)',
  'Quantities in the price list' => 'Mengenangaben in der Preisliste',
  'Conversation history (hours)' => 'Gesprächsverlauf (Stunden)',
  'Before replying, the assistant reads all messages from this period.' => 'Bevor er antwortet, liest der Assistent alle Nachrichten aus diesem Zeitraum.',
  'Donation types the assistant offers' => 'Spendenarten, die der Assistent anbietet',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => 'Wenn keine ausgewählt ist, werden alle offenen Typen angeboten. Wenn in Flux Donate ein neuer Typ geöffnet wird, weiß dies auch der Assistent.',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => 'Vorabprüfung der Quittung: Wenn der Kontakt eine Quittung sendet, vergleicht die KI den Betrag, den Empfänger und die IBAN mit der Spende, teilt dem Kontakt das Ergebnis mit, hängt die Datei an den Spendendatensatz an und übergibt den Chat an das Team zur endgültigen Genehmigung (markiert ihn nicht als bezahlt).',
  'Last line of the price list' => 'Letzte Zeile der Preisliste',
  'Payment details' => 'Zahlungsdetails',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => 'Wenn der Empfänger und die IBAN leer sind, werden diejenigen in WooCommerce › Zahlungen › Banküberweisung verwendet (das bei Bestellungen angezeigte Konto). Füllen Sie diese nur aus, wenn der Assistent ein anderes Konto verwenden soll.',
  'Recipient name' => 'Empfängername',
  'Transfer description' => 'Übertragungsbeschreibung',
  'Variables: {type}, {name}, {amount}, {quantity}' => 'Variablen: {type}, {name}, {amount}, {quantity}',
  'Donation page URL' => 'URL der Spendenseite',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => 'Der ausgewählte Typ und die ausgewählte Menge werden dem Link hinzugefügt (?flxb_opt=...&flxb_qty=...).',
  'Message after the payment details' => 'Nachricht nach den Zahlungsdetails',
  'Donation cancellation question' => 'Frage zur Spendenstornierung',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'Der Assistent storniert nur unbezahlte Spenden mit der Bestätigung der Person. Leer = Standardtext. Variablen: {bagis}, {tutar}.',
  'Message sent when the daily limit is reached' => 'Nachricht wird gesendet, wenn das Tageslimit erreicht ist',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'Wird einmal gesendet, wenn ein Chat das Antwortlimit des Tages erreicht. Der Chat wird an das Team übergeben. Setzen Sie es über das ⋮-Menü des Chats › Assistant-Nutzung zurück.',
  'Message sent when handing over to the team' => 'Nachricht wird bei Übergabe an das Team gesendet',
  'Message sent when the assistant cannot answer' => 'Nachricht wird gesendet, wenn der Assistent nicht antworten kann',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'Wenn die KI ausfällt, das Zeitlimit erreicht ist oder die Warteschlange zu lang wird, wird diese Nachricht gesendet und der Chat an das Team übergeben; Die Person bleibt nie ohne Antwort.',
  'Minimum wait before the holding message (s)' => 'Mindestwartezeit vor der/den Wartenachricht(en)',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => 'Die Haltenachricht wird erst so viele Sekunden nach der Nachricht der Person gesendet; In der Zwischenzeit versucht der Assistent es erneut.',
  'Longest time for one answer (s)' => 'Längste Zeit für eine Antwort(en)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'Hostinger kann Anfragen in ca. 60 Sekunden kürzen; 50 wird empfohlen.',
  'Numbers notified on handoff' => 'Nummern werden bei der Übergabe mitgeteilt',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'Wenn der Assistent einen Chat an das Team übergibt, wird aus derselben Leitung eine WhatsApp-Nachricht an diese Nummern gesendet: Name des Kontakts, Telefonnummer, Grund, letzte Nachrichten und Panel-Link. Trennen Sie durch Kommas oder neue Zeilen. Der Assistent spricht nicht mit diesen Nummern.',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => 'Wenn der Kontakt eine dieser Nachrichten schreibt, sendet der Assistent sofort die obige Übergabenachricht und schaltet sich in diesen Chat ein. Wenn es leer bleibt, wird die Beispielliste verwendet.',
  'Extra instructions for the assistant' => 'Zusätzliche Anweisungen für den Assistenten',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => 'Z.B. In Kocaeli werden Setzlinge gepflanzt. Sobald die Spende bestätigt ist, werden Zertifikate verschickt.',
  'Last message when a contact opts out' => 'Letzte Nachricht, wenn sich ein Kontakt abmeldet',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => 'Wenn jemand so etwas schreibt wie „Keine Nachricht an mich senden“, sendet der Assistent diese Nachricht und setzt ihn auf die Sperrliste. Eine auf der Sperrliste stehende Person erhält keine WhatsApp, E-Mail oder SMS; Verwalten Sie die Liste unter Chats › ☰ › Blocklist.',
  'Contact memory and background jobs' => 'Kontaktspeicher und Hintergrundjobs',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => 'Kontaktgedächtnis: Der Assistent merkt sich bleibende Details (Anrede, Namen von Verwandten, Nummern, Vorlieben); Abgelaufene Chats werden zusammengefasst',
  'Summarize a chat after it has been quiet for (hours)' => 'Fassen Sie einen Chat zusammen, nachdem es (Stunden) ruhig war.',
  'Maximum jobs at the same time' => 'Maximale Jobs gleichzeitig',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => 'Wie viele Personen können gleichzeitig beantwortet werden? Die Antworten des Assistenten stehen immer an erster Stelle. Zusammenfassungen beginnen nicht, während jemand beantwortet wird oder wartet. Jeder Job verwendet einen PHP-Worker: Bleiben Sie beim Shared Hosting unter der Hälfte des gesamten Worker-Limits Ihrer Websites (z. B. 20–30 von 60 Workern).',
  'Workers reserved for replies' => 'Für Antworten reservierte Mitarbeiter',
  'This many workers never take summaries or reminders.' => 'So viele Arbeitnehmer nehmen niemals Zusammenfassungen oder Erinnerungen entgegen.',
  'Summary hours' => 'Zusammenfassung Stunden',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => 'Zusammenfassungen werden nur zwischen diesen Stunden ausgeführt (mit Ausnahme einer manuellen „Jetzt zusammenfassen“). Wenn beide gleich sind, jederzeit.',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => 'Wenn jemand eine Sprachnachricht sendet, wandelt der Assistent diese in Text um und antwortet (der Text erscheint auch im Panel als Systemzeile).',
  'Longest voice message (sec)' => 'Längste Sprachnachricht (Sek.)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => 'Bei längeren Nachrichten sagt der Assistent: „Die Sprachnachricht war zu lang, als dass wir sie abhören konnten.“',
  'Voice message model (optional)' => 'Sprachnachrichtenmodell (optional)',
  'Cheap audio model (Gemini Flash Lite)' => 'Günstiges Audiomodell (Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'Muss ein OpenRouter-Modell sein, das Audio akzeptiert (Claude nicht). Ein OpenRouter-Schlüssel ist erforderlich.',
  'Images' => 'Bilder',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'Lassen Sie den Assistenten bei Bedarf ein Bild zeichnen (Tabelle, Bericht, Diagramm); Es geht als Bild an WhatsApp, der Text wird separat gesendet',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'Es wird der Bildrenderer Flux AI verwendet (Flux AI & MCP › Einstellungen › Bilder).',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'Kein Bildrenderer auf dem Server: Geben Sie eine Gotenberg-Adresse in Flux AI & MCP › Einstellungen › Bilder ein oder installieren Sie Imagick (SVG). Bis dahin zeichnet der Assistent keine Bilder.',
  'Works once Flux AI 0.2.0 or later is installed.' => 'Funktioniert, sobald Flux AI 0.2.0 oder höher installiert ist.',
  'Donation on behalf of someone' => 'Spende im Namen einer Person',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => 'Wenn die Spende auf den Namen einer anderen Person lautet und deren Nummer angegeben wurde (Kontaktkarte oder getippte Nummer), senden Sie die Bescheinigung auch an diese Nummer auf WhatsApp, sobald die Zahlung genehmigt wurde',
  'Message sent before the certificate' => 'Vor dem Zertifikat gesendete Nachricht',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => 'Anschließend wird die WhatsApp-Zertifikatsnachricht von Flux Certificates versendet. Variablen: {ad}, {bagisci}, {bagis}, {brand}.',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => 'Wenn eine Person danach fragt, richtet der Assistent eine Erinnerung ein (z. B. „erinnere mich jeden Monat an das Pflanzen eines Setzlings“, „sende mir jeden Monat deine neuesten Projekte“, „frage mich jeden Monat nach einem Setzling“); Wenn es fällig ist, schreibt und sendet der Assistent die Nachricht',
  'When no time is given' => 'Wenn keine Zeit gegeben ist',
  'At most per person' => 'Höchstens pro Person',
  'Staff (Flux Roles)' => 'Mitarbeiter (Flux-Rollen)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'Funktioniert, sobald Flux Roles 1.1.0 installiert ist: Benutzer, deren Nummer in Profil › WhatsApp-Nummer festgelegt ist, erhalten zusätzliche Hilfstools basierend auf ihren Berechtigungen.',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => 'Geben Sie Mitarbeitern mit Erlaubnis zusätzliche Hilfstools (Spende im Namen einer Person mit Zahlungslink, meine Spender, allgemeiner Bericht).',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => 'Benachrichtigen Sie die Mitarbeiter über WhatsApp, wenn eine von ihnen empfohlene Spende bezahlt oder storniert wird',
  'First message to the donor for a donation opened by staff' => 'Erste Nachricht an den Spender für eine Spende, geöffnet durch Mitarbeiter',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'Hallo {ad}🌱 Deine {bagis}-Spendenanfrage über {personel} ist eingegangen. Sie können mit den untenstehenden Angaben bezahlen.',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Es folgen der Zahlungslink und die Bankdaten. Variablen: {ad}, {adsoyad}, {personel}, {bagis}.',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'Wenn eine von einem Mitarbeiter empfohlene Spende ausgezahlt und die entsprechenden Bescheinigungen ausgestellt werden, senden Sie diese ebenfalls über WhatsApp an den Mitarbeiter (genau wie den Spender).',
  'Message sent to the staff member before the certificate' => 'Nachricht, die vor der Urkunde an den Mitarbeiter gesendet wird',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variablen: {ad}, {bagisci}, {bagis}, {no}, {brand}.',
  'How many times staff can resend a donation\'s certificate' => 'Wie oft können Mitarbeiter eine Spendenbescheinigung erneut senden?',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'Der Assistent listet die Empfänger auf und bittet vor dem Senden um eine Bestätigung. 0: aus.',
  'Code verification for record lookups' => 'Codeüberprüfung für Datensatzsuche',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => 'Wenn eine Person nach ihren Unterlagen fragt und ihre Nummer verborgen ist (oder sie mit einer anderen Nummer/E-Mail-Adresse gespendet hat), senden Sie einen Code an die angegebene Nummer oder E-Mail-Adresse. Nach der Überprüfung werden auch die Datensätze angezeigt',
  'Code validity (min)' => 'Codegültigkeit (min.)',
  'Maximum failed attempts' => 'Maximale Fehlversuche',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => 'Es zählen Codes, die nicht versendet werden konnten, falsche Codes und abgelaufene Codes. Bei Erreichen des Limits erhält die Person die folgende Nachricht und das Team wird benachrichtigt; Der Assistent beantwortet weiterhin andere Fragen, teilt jedoch 24 Stunden lang keine Datensatzdetails mit.',
  'Code to phone' => 'Code zum Telefonieren',
  'WhatsApp, SMS if it fails' => 'WhatsApp, SMS, wenn es fehlschlägt',
  'WhatsApp only' => 'Nur WhatsApp',
  'SMS only' => 'Nur SMS',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => 'SMS wird verwendet, wenn Flux Mail über eine SMS-Verbindung verfügt (z. B. Netgsm).',
  'Message when verification fails' => 'Meldung, wenn die Überprüfung fehlschlägt',
  'WhatsApp/SMS code message' => 'WhatsApp/SMS-Codenachricht',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => 'Standardtext, falls leer. Variablen: {kod}, {dk}, {marka}. Der E-Mail-Text wird in Flux Mail › E-Mail-Vorlagen bearbeitet.',
  'Site content' => 'Inhalt der Website',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'Lassen Sie den Assistenten nach veröffentlichten Inhalten der Website suchen (z. B. „Haben Sie einen Beitrag zum Thema Baumpflanzung“)?',
  'Content types to search' => 'Zu durchsuchende Inhaltstypen',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'Es werden nur veröffentlichte Inhalte ohne Passwort zurückgegeben. Entwürfe, private und passwortgeschützte Inhalte werden niemals angezeigt.',
  'Categories and tags never to share' => 'Kategorien und Tags dürfen niemals geteilt werden',
  'e.g. corporate-offers, internal-notice' => 'z.B. Firmenangebote, interne Bekanntmachung',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => 'Name oder Slug, durch Komma getrennt. Um ein einzelnes Element auszublenden, aktivieren Sie auf dem Bearbeitungsbildschirm die Option „Diesen Inhalt nicht vom Assistenten teilen lassen“.',
  'Team group' => 'Teamgruppe',
  'WhatsApp group' => 'WhatsApp-Gruppe',
  '— Not selected —' => '— Nicht ausgewählt —',
  'Groups the line is a member of. If a group you just created is missing,' => 'Gruppen, denen die Linie angehört. Wenn eine Gruppe, die Sie gerade erstellt haben, fehlt,',
  'refresh the list' => 'Aktualisieren Sie die Liste',
  'Post incoming messages and replies (assistant, team, automatic) to this group' => 'Veröffentlichen Sie eingehende Nachrichten und Antworten (Assistent, Team, automatisch) in dieser Gruppe',
  'Send handoff notifications to this group instead of each number; the numbers above are mentioned in the message' => 'Senden Sie Übergabebenachrichtigungen an diese Gruppe statt an jede einzelne Nummer. Die oben genannten Nummern werden in der Nachricht erwähnt',
  'Last post to the group failed: ' => 'Der letzte Beitrag in der Gruppe ist fehlgeschlagen:',
  'Price list preview' => 'Vorschau der Preisliste',
  'Enter an AI key and model first so the assistant can work.' => 'Geben Sie zunächst einen KI-Schlüssel und ein Modell ein, damit der Assistent arbeiten kann.',
  'The assistant will not reply right now: ' => 'Der Assistent antwortet derzeit nicht:',
