  'No records in this range.' => 'Keine Datensätze in diesem Bereich.',
  'Replies' => 'Antworten',
  'Handoff' => 'Übergabe',
  'Only real chats are counted; test chat and benchmark are excluded. "Confirmed" means donations created by the assistant and marked paid.' => 'Es werden nur echte Chats gezählt; Test-Chat und Benchmark sind ausgeschlossen. „Bestätigt“ bedeutet vom Assistenten erstellte und als bezahlt markierte Spenden.',
  'With the team / paused' => 'Mit dem Team / pausiert',
  'Donation record created' => 'Spendendatensatz erstellt',
  'The assistant has not replied to any chat yet.' => 'Der Assistent hat noch auf keinen Chat geantwortet.',
  'Load more' => 'Mehr laden',
  'Address: {h}' => 'Adresse: {h}',
  '{n} assistant messages' => '{n}-Assistentenmeldungen',
  'Donation #{id}' => 'Spende #{id}',
  'Version {id}' => 'Version {id}',
  'Change note (e.g. Added sacrifice question)' => 'Notiz ändern (z. B. Opferfrage hinzugefügt)',
  'Assistant instructions' => 'Anweisungen des Assistenten',
  'The main text describing how the assistant talks and the flow. Prices, donation types, bank details and what is known about the contact are added automatically on every reply. {brand} becomes the organisation name and {{belge:kisa-ad}} becomes that document\'s content.' => 'Der Haupttext beschreibt, wie der Assistent spricht und wie er abläuft. Preise, Spendenarten, Bankdaten und die Informationen zum Kontakt werden bei jeder Antwort automatisch hinzugefügt.{brand} wird zum Namen der Organisation und {{belge:kisa-ad}} wird zum Inhalt dieses Dokuments.',
  'Publish now' => 'Jetzt veröffentlichen',
  'New version saved' => 'Neue Version gespeichert',
  'Save as new version' => 'Als neue Version speichern',
  'Show the full text sent to the model' => 'Zeigt den vollständigen Text an, der an das Modell gesendet wurde',
  'Unsaved text' => 'Nicht gespeicherter Text',
  'Test with this text' => 'Testen Sie mit diesem Text',
  'Versions' => 'Versionen',
