  'Diff: live → {v}' => 'Diff: live →{v}',
  'Show diff' => 'Diff. anzeigen',
  'Published' => 'Veröffentlicht',
  'Publish' => 'Veröffentlichen',
  'Ready-made messages sent by the server' => 'Vom Server gesendete vorgefertigte Nachrichten',
  'The model does not write these; they are generated from your settings.' => 'Das Modell schreibt diese nicht; Sie werden aus Ihren Einstellungen generiert.',
  'Change in settings' => 'Änderung der Einstellungen',
  '(empty)' => '(leer)',
  'Full text sent to the model (sample chat)' => 'Volltext an das Model gesendet (Beispiel-Chat)',
  'Extra documents' => 'Zusätzliche Dokumente',
  'Add FAQs, campaigns, planting locations and similar information as separate documents. If you write {{belge:kisa-ad}} in the instructions, the document is placed there. A document set to "read when needed" is only read when the topic comes up, which costs less for long documents.' => 'Fügen Sie FAQs, Kampagnen, Pflanzorte und ähnliche Informationen als separate Dokumente hinzu. Wenn Sie in der Anleitung {{belge:kisa-ad}} schreiben, wird das Dokument dort abgelegt. Ein Dokument, das auf „Bei Bedarf lesen“ eingestellt ist, wird nur gelesen, wenn das Thema auftaucht, was bei langen Dokumenten weniger kostet.',
  'New document' => 'Neues Dokument',
  'No documents yet.' => 'Noch keine Dokumente.',
  'Copy to use in the instructions' => 'Kopieren Sie es, um es in der Anleitung zu verwenden',
  'Delete the document “{t}”?' => 'Dokument „{t}“ löschen?',
  'automatic' => 'automatisch',
