  'Prices are input / output per 1M tokens (USD). The selected model is used only here.' => 'Die Preise verstehen sich als Input/Output pro 1 Mio. Token (USD). Das ausgewählte Modell wird nur hier verwendet.',
  'E.g. Look at Ahmet\'s chat and make the price answer shorter. / Hand over to the team when asked about Qurban donations.' => 'Z.B. Schauen Sie sich Ahmets Chat an und verkürzen Sie die Preisantwort. / Übergabe an das Team, wenn es um Qurban-Spenden gebeten wird.',
  'Search sessions…' => 'Suchsitzungen...',
  '+ New session' => '+ Neue Sitzung',
  'No matching session.' => 'Keine passende Sitzung.',
  'No saved sessions yet. A session is saved automatically with your first message.' => 'Noch keine gespeicherten Sitzungen. Eine Sitzung wird automatisch mit Ihrer ersten Nachricht gespeichert.',
