  'Unarchive' => 'Dearchivieren',
  'Delete this session? This cannot be undone.' => 'Diese Sitzung löschen? Dies kann nicht rückgängig gemacht werden.',
  'The live instructions changed after this session; starting a new session is recommended.' => 'Die Live-Anweisungen änderten sich nach dieser Sitzung; Es wird empfohlen, eine neue Sitzung zu beginnen.',
  'Write what you want to change. If you mention a person\'s or a number\'s chat, the AI finds it, asks your permission to read it, updates the instructions and tries them itself in the test chat on the right. Publishing needs your approval.' => 'Schreiben Sie, was Sie ändern möchten. Wenn Sie den Chat einer Person oder einer Nummer erwähnen, findet die KI ihn, bittet Sie um Erlaubnis, ihn lesen zu dürfen, aktualisiert die Anweisungen und probiert sie selbst im Test-Chat rechts aus. Für die Veröffentlichung ist Ihre Zustimmung erforderlich.',
  'Draft updated' => 'Entwurf aktualisiert',
  'Permission to read a chat' => 'Erlaubnis, einen Chat zu lesen',
  'Allow' => 'Erlauben',
  'Always allow in this session' => 'In dieser Sitzung immer zulassen',
  'Don\'t allow' => 'Nicht zulassen',
