  'Tokens are the memory size the assistant reads for this contact on every reply (approx.; 3.5 characters = 1 token).' => 'Token sind die Speichergröße, die der Assistent bei jeder Antwort für diesen Kontakt liest (ca.; 3,5 Zeichen = 1 Token).',
