  'People who are writing are answered first; no summary starts while someone is being answered or waiting. Chats quiet for {h} hours are summarized only between {w}. At most {m} jobs run at once, {r} workers are reserved for replies (a benchmark counts as one). Refreshes every 5 s.' => 'Wer schreibt, dem wird zuerst geantwortet; Es wird keine Zusammenfassung gestartet, während jemand beantwortet wird oder wartet. Chats, die für {h} Stunden ruhig waren, werden nur zwischen {w} zusammengefasst. Bei den meisten {m}-Jobs, die gleichzeitig ausgeführt werden, sind {r}-Worker für Antworten reserviert (ein Benchmark zählt als einer). Wird alle 5 s aktualisiert.',
