  'Assistant + judge' => 'Assistent + Richter',
  'Per scenario' => 'Pro Szenario',
  'Success is attributed to the assistant model. Runs before 1.6.3 did not separate assistant and judge, so they show as "Assistant + judge".' => 'Der Erfolg wird dem Assistentenmodell zugeschrieben. Bei Läufen vor 1.6.3 wurden Assistent und Richter nicht getrennt, daher werden sie als „Assistent + Richter“ angezeigt.',
  'Run {n} scenarios' => 'Führen Sie {n}-Szenarien aus',
  'Loading model prices for the cost estimate…' => 'Modellpreise für den Kostenvoranschlag werden geladen...',
  'The selected model\'s price is unknown; no estimate.' => 'Der Preis des ausgewählten Modells ist unbekannt; keine Schätzung.',
  'Estimated cost: ~{c}' => 'Geschätzte Kosten: ~{c}',
  'assistant {a} + judge {j}' => 'Assistent {a}+ Richter {j}',
  'Based on average token usage of {n} past scenario results; actual cost per scenario may vary.' => 'Basierend auf der durchschnittlichen Token-Nutzung von {n} in früheren Szenarioergebnissen; Die tatsächlichen Kosten pro Szenario können variieren.',
  'No runs yet; default estimate: ~{i} input / {o} output tokens per donor message.' => 'Noch keine Läufe; Standardschätzung: ~{i} Eingabe-/{o} Ausgabe-Token pro Spendernachricht.',
  'The estimate exceeds the cost limit; the run stops when the limit is reached.' => 'Der Kostenvoranschlag überschreitet die Kostengrenze; Der Lauf stoppt, wenn das Limit erreicht ist.',
  'New run' => 'Neuer Lauf',
  'Scenarios are played like in the test chat: no WhatsApp message is sent and no record is created. The model is really called; the cost is charged to your AI account (OpenRouter or Anthropic) and the run stops when the limit is reached.' => 'Es werden Szenarien wie im Testchat abgespielt: Es wird keine WhatsApp-Nachricht gesendet und kein Datensatz erstellt. Das Modell heißt wirklich; Die Kosten werden Ihrem AI-Konto (OpenRouter oder Anthropic) belastet und der Lauf stoppt, wenn das Limit erreicht ist.',
  'Cost limit (USD)' => 'Kostenlimit (USD)',
