  'All chats, tool calls and judge log' => 'Alle Chats, Tool-Anrufe und Richterprotokoll',
  'Report' => 'Bericht',
  'Delete this run and its results?' => 'Diesen Lauf und seine Ergebnisse löschen?',
  'Running in the background on the server; it continues even if you close the page.' => 'Läuft im Hintergrund auf dem Server; es wird auch dann fortgesetzt, wenn Sie die Seite schließen.',
  'Watch results live' => 'Sehen Sie sich die Ergebnisse live an',
