  'The remaining scenarios were not counted as failed. Check the provider budget, credit or key, then use Continue to resume where it stopped.' => 'Die übrigen Szenarien wurden nicht als gescheitert gewertet. Überprüfen Sie das Budget, das Guthaben oder den Schlüssel des Anbieters und nutzen Sie dann „Weiter“, um dort fortzufahren, wo es aufgehört hat.',
  'Handed off when it should' => 'Übergeben, wann es sollte',
