  'Messages (in order)' => 'Nachrichten (in der Reihenfolge)',
  '{tur}, {birim} and {brand} can be used. If there are only customer messages, the assistant replies to each in turn. If you add assistant messages it becomes a continuation scenario: the written history is given as-is and the assistant replies only to the last customer message.' => 'Es können {tur}, {birim} und {brand} verwendet werden. Liegen nur Kundennachrichten vor, antwortet der Assistent der Reihe nach. Wenn Sie Assistentennachrichten hinzufügen, entsteht ein Fortsetzungsszenario: Der geschriebene Verlauf wird unverändert angezeigt und der Assistent antwortet nur auf die letzte Kundennachricht.',
  'E.g. payment_info, cancel_donation, receipt_check. Tools disabled on this site are not checked.' => 'Z.B. payment_info, cancel_donation, quitt_check. Auf dieser Website deaktivierte Tools werden nicht überprüft.',
  'Who is writing?' => 'Wer schreibt?',
  'Starting state (test)' => 'Ausgangszustand (Test)',
  'The scenario runs isolated like the test chat; what you select here exists only in this test. In a customer message, {kod} becomes the verification code from the test panel.' => 'Das Szenario läuft wie der Testchat isoliert ab; Was Sie hier auswählen, existiert nur in diesem Test. In einer Kundennachricht wird {kod} zum Verifizierungscode des Testpanels.',
  'End state' => 'Endzustand',
  'When the conversation ends, the test state is checked (was a donation opened, canceled, a code sent…). Tools disabled on this site are not checked.' => 'Wenn das Gespräch endet, wird der Teststatus überprüft (wurde eine Spende eröffnet, abgebrochen, ein Code gesendet...). Auf dieser Website deaktivierte Tools werden nicht überprüft.',
  'Judge criterion' => 'Beurteilungskriterium',
  'If empty, the judge is not called. Put quality expectations that cannot be written as rules here.' => 'Wenn es leer ist, wird der Richter nicht aufgerufen. Stellen Sie hier Qualitätserwartungen dar, die sich nicht als Regeln formulieren lassen.',
