  'Media folder' => 'Medienordner',
  'Cannot write to uploads/flx-chat; incoming photos, voice notes and documents cannot be saved. Check folder permissions.' => 'Kann nicht in Uploads/flx-chat schreiben; Eingehende Fotos, Sprachnotizen und Dokumente können nicht gespeichert werden. Überprüfen Sie die Ordnerberechtigungen.',
