  '%s: connection details' => '%s: Verbindungsdetails',
  'Using Flux Mail connection: %s.' => 'Verwenden der Flux Mail-Verbindung: %s.',
  'Still using the old provider in Flux Certificates; move the connection to Flux Mail and select it here.' => 'Ich verwende immer noch den alten Anbieter für Flux-Zertifikate. Verschieben Sie die Verbindung zu Flux Mail und wählen Sie sie hier aus.',
  'Using the Evolution provider from Flux Certificates.' => 'Verwendung des Evolution-Anbieters von Flux Certificates.',
  'API URL, key and instance are entered in this plugin.' => 'In diesem Plugin werden API-URL, Schlüssel und Instanz eingetragen.',
  '%s: line status' => '%s: Leitungsstatus',
  'Phone connected (last seen %s).' => 'Telefon verbunden (zuletzt gesehen %s).',
  'Not tested yet. Press "Test connection".' => 'Noch nicht getestet. Drücken Sie „Verbindung testen“.',
  'Phone not connected (state: %1$s, %2$s). Reconnect with "Connect with QR".' => 'Telefon nicht verbunden (Status: %1$s, %2$s). Stellen Sie die Verbindung mit „Mit QR verbinden“ wieder her.',
  '%s: Evolution API version' => '%s: Evolution-API-Version',
  'Evolution API %s is in use. Replies to hidden-number (@lid) contacts may fail; update the server to 2.3 or later.' => 'Die Evolution API %s wird verwendet. Antworten auf Kontakte mit versteckten Nummern (@lid) schlagen möglicherweise fehl; Aktualisieren Sie den Server auf 2.3 oder höher.',
  '%s: webhook (incoming messages)' => '%s: Webhook (eingehende Nachrichten)',
  'No events have arrived from Evolution; incoming messages will not show in the panel. Press "Set up webhook".' => 'Von Evolution sind keine Ereignisse eingetroffen; Eingehende Nachrichten werden nicht im Panel angezeigt. Klicken Sie auf „Webhook einrichten“.',
  'Last event arrived %s. The line may just be quiet; send yourself a message or set up the webhook again to be sure.' => 'Das letzte Ereignis ist eingetroffen %s. Möglicherweise ist die Leitung einfach nur ruhig; Senden Sie sich zur Sicherheit eine Nachricht oder richten Sie den Webhook erneut ein.',
  'Last event arrived %s.' => 'Das letzte Ereignis ist eingetroffen %s.',
  'Flux Mail integration' => 'Flux Mail-Integration',
  'Active: WhatsApp connections are taken from Communication › Connections.' => 'Aktiv: WhatsApp-Verbindungen werden aus Kommunikation › Verbindungen übernommen.',
  'Flux Mail is not active; connections are taken from Flux Certificates or from this plugin.' => 'Flux Mail ist nicht aktiv; Verbindungen werden von Flux-Zertifikaten oder von diesem Plugin übernommen.',
  'Flux Certificates integration' => 'Integration von Flux-Zertifikaten',
  'Active: certificates can be created and sent from chats.' => 'Aktiv: Zertifikate können aus Chats erstellt und versendet werden.',
  'Flux Certificates is not active; certificate actions in chats are off.' => 'Flux-Zertifikate sind nicht aktiv; Zertifikataktionen in Chats sind deaktiviert.',
  'Flux Donate integration' => 'Flux Donate-Integration',
  'Active: donation records, receipt matching and the assistant are available from chats.' => 'Aktiv: Spendenaufzeichnungen, Quittungsabgleich und der Assistent sind über Chats verfügbar.',
  'Flux Donate is not active; donation records, receipt matching and the donation assistant are off.' => 'Flux Donate ist nicht aktiv; Spendenaufzeichnungen, Belegabgleich und der Spendenassistent sind deaktiviert.',
  'The Flux AI & MCP plugin is not installed; AI features (suggestions, assistant, receipt reading, voice messages, summaries) are off. Install Flux AI and enter the key there.' => 'Das Flux AI & MCP-Plugin ist nicht installiert; KI-Funktionen (Vorschläge, Assistent, Vorlesen von Belegen, Sprachnachrichten, Zusammenfassungen) sind deaktiviert. Installieren Sie Flux AI und geben Sie dort den Schlüssel ein.',
  'No key has been entered in Flux AI; message suggestions and the assistant are off.' => 'In Flux AI wurde kein Schlüssel eingegeben; Nachrichtenvorschläge und der Assistent sind ausgeschaltet.',
  'Key saved but no model selected.' => 'Schlüssel gespeichert, aber kein Modell ausgewählt.',
  'No provider key has been entered in Flux AI for the selected model (%s).' => 'Für das ausgewählte Modell (%s) wurde in Flux AI kein Providerschlüssel eingetragen.',
  'Key saved, model: %s. Use "Test connection" for a live check.' => 'Schlüssel gespeichert, Modell: %s. Nutzen Sie „Verbindung testen“ für einen Live-Check.',
  'Donation assistant' => 'Spendenassistent',
  'Off.' => 'Aus.',
  'AI key or model is missing.' => 'KI-Schlüssel oder Modell fehlt.',
  'On but not replying: ' => 'An, antwortet aber nicht:',
  'On. Donation types offered: %s.' => 'Auf. Angebotene Spendenarten: %s.',
  '%s does not support tools; choose a tool-capable model for the assistant.' => '%s unterstützt keine Tools; Wählen Sie ein werkzeugfähiges Modell für den Assistenten.',
  'Receipt reading model' => 'Modell zum Lesen von Quittungen',
  '%s cannot read images; the receipt pre-check will not work. Choose an image-capable receipt reading model.' => '%s kann keine Bilder lesen; Die Quittungsvorprüfung funktioniert nicht. Wählen Sie ein bildfähiges Beleglesemodell.',
  'Assistant payment details' => 'Zahlungsdetails des Assistenten',
  'Recipient name and IBAN set.' => 'Empfängername und IBAN eingestellt.',
  'Recipient name or IBAN missing; bank details cannot be sent after confirmation.' => 'Empfängername oder IBAN fehlen; Bankdaten können nach Bestätigung nicht übermittelt werden.',
  'Donation page link' => 'Link zur Spendenseite',
  'Donation page not found; the assistant will not send a link.' => 'Spendenseite nicht gefunden; Der Assistent sendet keinen Link.',
  'Background requests' => 'Hintergrundanfragen',
  'The site could not send a background request to itself (%1$s: %2$s). Queued replies and the benchmark may move slowly; a security plugin or the server firewall may be blocking /wp-json/flx-chat/ requests.' => 'Die Site konnte keine Hintergrundanforderung an sich selbst senden (%1$s: %2$s). Antworten in der Warteschlange und der Benchmark bewegen sich möglicherweise langsam; Möglicherweise blockiert ein Sicherheits-Plugin oder die Server-Firewall /wp-json/flx-chat/-Anfragen.',
  'error' => 'Fehler',
  'warning' => 'Warnung',
  'ok' => 'ok',
  'Your {marka} verification code: {kod}' => 'Ihr {marka}-Bestätigungscode: {kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'Der Code ist für {dk}-Minuten gültig. Geben Sie es in Ihren WhatsApp-Chat mit uns ein. Wenn Sie nicht danach gefragt haben, ignorieren Sie diese Nachricht.',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => 'Etwas ist schief gelaufen; Unser Team wird sich so schnell wie möglich mit Ihnen in Verbindung setzen 🌱 In der Zwischenzeit können Sie gerne weitere Fragen stellen.',
  'Verification attempt failed (%1$d/%2$d): %3$s' => 'Überprüfungsversuch fehlgeschlagen (%1$d/%2$d): %3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'Die Person wollte ihre Unterlagen einsehen, konnte aber nicht verifiziert werden; Jemand aus dem Team sollte sich melden',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => 'E-Mail konnte nicht gesendet werden (überprüfen Sie die Flux Mail › SMTP-Einstellungen)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'Der Assistent hat einen Bestätigungscode für %1$s(%2$s) gesendet.',
  'code expired' => 'Code abgelaufen',
  'wrong code' => 'falscher Code',
  'The person verified the code for %s; it is added to their record lookups.' => 'Die Person hat den Code für %s überprüft; Es wird zu ihren Datensatzsuchen hinzugefügt.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'Claude-Modelle können keine Audiodaten lesen. Wählen Sie unter Einstellungen › AI › Sprachnachrichtenmodell ein audiofähiges OpenRouter-Modell aus.',
  'The audio could not be transcribed.' => 'Der Ton konnte nicht transkribiert werden.',
  'The audio file could not be read.' => 'Die Audiodatei konnte nicht gelesen werden.',
  'Voice message (%1$s) transcribed: %2$s' => 'Sprachnachricht (%1$s) transkribiert: %2$s',
  'Voice message (%1$s) could not be processed: %2$s' => 'Sprachnachricht (%1$s) konnte nicht verarbeitet werden: %2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => 'Diese Aktion ist in einer offiziellen WhatsApp Cloud-API-Linie nicht verfügbar.',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'WhatsApp 24-Stunden-Regel: Der Kontakt hat in den letzten 24 Stunden nicht geschrieben, daher sendet die Cloud API keine Freiformnachricht; Es kann nur eine genehmigte Vorlage gesendet werden. Versuchen Sie es noch einmal, sobald sie schreiben.',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Eine Cloud-API-Zeile benötigt Flux Mail 1.10.0 oder höher.',
  'The Cloud API cannot send to this address (hidden number or group).' => 'Die Cloud API kann nicht an diese Adresse senden (versteckte Nummer oder Gruppe).',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'Das Cloud-API-Konto konnte nicht erreicht werden (Link › Verbindungen).',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Eine Cloud-API-Zeile hat keinen QR-Code; Das Konto wird unter „Verbindungen“ eingerichtet.',
  'The file could not be prepared.' => 'Die Datei konnte nicht vorbereitet werden.',
  'Flux AI has no image support.' => 'Flux AI bietet keine Bildunterstützung.',
  'The image could not be rendered.' => 'Das Bild konnte nicht gerendert werden.',
  'The assistant\'s image could not be sent: ' => 'Das Bild des Assistenten konnte nicht gesendet werden:',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => 'Hallo {first_name}, wir haben Ihren Spendendatensatz erstellt: {donation}, insgesamt {amount}.{bank} Nach der Bezahlung können Sie hier die Quittung senden. Danke schön.',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'Hallo {first_name}, Ihre Spende wurde erfasst: {donation}, insgesamt {amount}.' . chr(10) . '' . chr(10) . 'Vielen Dank für Ihre Unterstützung.',
  'The plugin that would run this scenario is inactive.' => 'Das Plugin, das dieses Szenario ausführen würde, ist inaktiv.',
  'This user is not allowed to use the staff tools.' => 'Dieser Benutzer darf die Mitarbeitertools nicht verwenden.',
  '%1$s linked this chat to staff member %2$s' => '%1$s hat diesen Chat mit dem Mitarbeiter %2$s verknüpft',
  '%s removed the staff link of this chat' => '%s hat den Mitarbeiterlink dieses Chats entfernt',
  'Chat linked to staff member' => 'Chat mit Mitarbeiter verknüpft',
  'Staff link removed' => 'Mitarbeiterlink entfernt',
  '— Not staff —' => '– Kein Personal –',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'WhatsApp verbirgt die Nummer dieser Person, sodass der Assistent das Personal nicht anhand der Nummer erkennen kann. Wenn diese Person zu Ihrem Team gehört, verlinken Sie sie hier und der Assistent öffnet die Mitarbeitertools.',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => 'Der Assistent erkennt Mitarbeiter anhand der Nummer in ihrem Flux Roles-Profil. Wenn die Nummer nicht übereinstimmt, können Sie sie hier verlinken; Bei einem Chat mit einer bekannten Nummer steht die Nummer an erster Stelle.',
  'This channel is not available right now.' => 'Dieser Kanal ist derzeit nicht verfügbar.',
  'Site chat' => 'Site-Chat',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => 'Alle Nachrichten von WhatsApp, Site-Chat und anderen Kanälen erscheinen hier live. Wählen Sie links einen Chat aus.',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => 'WhatsApp (Evolution API) Callcenter: Eingehende und ausgehende Nachrichten live sehen, neuen Chat starten, vorgefertigte Antworten, Tags, Aufgaben, interne Notizen, automatische Antworten; Registrierung von Spende (Flux Donate) und Zertifikat (Flux Certificates) über den Chat, Belegabgleich. Antwortvorschlag mit künstlicher Intelligenz und automatischer Spendenassistent mit OpenRouter.',
  'Çağrı Merkezi' => 'Callcenter',
  'Sohbetler' => 'Chats',
  'AI asistan' => 'KI-Assistent',
  'Çağrı Merkezi Ayarları' => 'Callcenter-Einstellungen',
  'Ayarlar' => 'Einstellungen',
  'Çağrı Merkezi için JavaScript gerekli.' => 'Für das Call Center ist JavaScript erforderlich.',
  'Bu sayfaya erişim yetkiniz yok.' => 'Sie haben keine Berechtigung, auf diese Seite zuzugreifen.',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => 'Überwachen Sie die Chats, die der Assistent bearbeitet, bearbeiten Sie seine Anweisungen und Dokumente und testen Sie Änderungen, bevor Sie sie veröffentlichen.',
  'Asistan ayarları' => 'Assistenteneinstellungen',
  'Bu sayfa için JavaScript gerekli.' => 'Diese Seite erfordert JavaScript.',
  'Kapalı' => 'Geschlossen',
  'Açık, 5 dakika' => 'An, 5 Minuten',
  'Açık, 1 saat' => 'An, 1 Stunde',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'AI benötigt das Flux AI & MCP-Plugin; Installieren und aktivieren Sie es und geben Sie dann den Schlüssel in Flux AI & MCP › Einstellungen ein.',
  'Yapay zekâ modeli seçilmemiş.' => 'Kein KI-Modell ausgewählt.',
  'Flux AI\'de Anthropic (Claude) anahtarı girilmemiş.' => 'In Flux AI wurde kein Anthropic (Claude)-Schlüssel eingegeben.',
  'Flux AI\'de OpenRouter anahtarı girilmemiş.' => 'In Flux AI wurde kein OpenRouter-Schlüssel eingegeben.',
  'Model listesi için Flux AI & MCP eklentisi gerekli.' => 'Die Modellliste benötigt das Flux AI & MCP Plugin.',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'Flux Call Center: KI-Funktionen (Vorschläge, Assistent, Vorlesen von Belegen, Sprachnachrichten, Zusammenfassungen) erfordern das Flux AI & MCP-Plugin. Installieren und aktivieren Sie es. Im Call Center gespeicherte Schlüssel werden automatisch dorthin verschoben.',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'Flux Call Center: Ein anderer %s-Schlüssel ist bereits in Flux AI gespeichert und wird verwendet. Der alte Callcenter-Schlüssel wurde nicht verschoben und wird nicht mehr verwendet.',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'Flux Call Center: KI-Tasten wurden zu Flux AI verschoben. Von nun an werden Schlüssel, Ausgabenlimits und Protokolle in Flux AI verwaltet; Die Modellauswahl bleibt im Call Center.',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'Das Flux Donate-Plugin ist nicht aktiv; Daraus übernimmt der Assistent Spendenarten und -preise.',
  'Flux Donate\'ta açık bağış türü yok (Bağış türleri sayfasından bir türü açın).' => 'In Flux Donate gibt es keinen offenen Spendentyp (öffnen Sie einen auf der Seite „Spendentypen“).',
  'Asistan için seçilen bağış türleri kapalı ya da fiyatsız; açık bir tür seçin ya da seçimi boş bırakın.' => 'Die für den Assistenten ausgewählten Spendenarten sind geschlossen oder haben keinen Preis; Wählen Sie einen offenen Typ aus oder lassen Sie die Auswahl leer.',
  'Açık bağış türlerinin hiçbirinde fiyat yok (Flux Donate › Bağış türleri › seçenek fiyatı).' => 'Für keine der offenen Spendenarten gibt es einen Preis (Flux Donate › Spendenarten › Optionspreis).',
