  'Dekontunuzu aldık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'Wir haben Ihre Quittung erhalten, vielen Dank 🌱 Wir werden uns so schnell wie möglich bezüglich Ihrer Zahlung bei Ihnen melden.',
  'Dekontunuzu aldık, teşekkür ederiz 🌱 Bağışınız onaylandı.' => 'Wir haben Ihre Quittung erhalten, vielen Dank 🌱 Ihre Spende ist bestätigt.',
  'Bu dekontu daha önce almıştık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'Wir haben diese Quittung bereits erhalten, vielen Dank 🌱 Wir werden uns schnellstmöglich bezüglich Ihrer Zahlung bei Ihnen melden.',
  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => 'Diese Quittung scheint bereits zuvor in unser System hochgeladen worden zu sein. Die gleiche Quittung kann nicht für eine zweite Spende verwendet werden. Wenn Sie eine andere Zahlung getätigt haben, senden Sie bitte diese Quittung; Unser Team wird dies auch überprüfen.',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => 'Wir haben Ihre Quittung erhalten. Der darauf angegebene Betrag (%1$s) scheint nicht mit Ihrem Spendenbetrag (%2$s) übereinzustimmen. Könnten Sie es überprüfen? Wenn Sie eine andere Zahlung vorgenommen haben, können Sie hier schreiben; Unser Team wird auch einen Blick darauf werfen.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Wir haben Ihre Quittung erhalten, aber der darauf angegebene Empfänger scheint nicht unser Verein zu sein. Spenden erfolgen ausschließlich auf unser Konto im Namen von „%s“. Könnten Sie das überprüfen? Unser Team wird auch einen Blick darauf werfen.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Wir haben Ihre Quittung erhalten, aber der darauf angegebene Empfänger scheint nicht mit unserem Konto übereinzustimmen. Könnten Sie das überprüfen? Unser Team wird auch einen Blick darauf werfen.',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => 'Die von Ihnen gesendete Datei sieht nicht wie ein Zahlungsbeleg aus. Wenn Sie bezahlt haben, können Sie hier die Quittung oder einen Screenshot des Zahlungsbildschirms senden.',
