  '+ Yeni rapor' => '+ Neuer Bericht',
  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => 'Die Nummer des Empfängers stammt aus Benutzer › Profil › WhatsApp-Nummer; Berechtigungen von Benutzern › Rollen und Zugriff (Berichte empfangen, Gesamtbericht anzeigen, Berichte verwalten). Berichte werden zum gewählten Zeitpunkt verschickt; Ohne einen Server-Scheduler werden sie beim nächsten Website-Besuch oder bei der nächsten Nutzung des Chat-Panels gesendet.',
  'Geçersiz telefon numarası.' => 'Ungültige Telefonnummer.',
  'Önce Ayarlar › Bağlantılar bölümünden bir WhatsApp bağlantısı ekleyin.' => 'Fügen Sie zunächst unter Einstellungen › Verbindungen eine WhatsApp-Verbindung hinzu.',
