  'Bu mesaj yeniden gönderilemez.' => 'Diese Nachricht kann nicht erneut gesendet werden.',
  'Bu mesaja tepki verilemez.' => 'Auf diese Nachricht kann nicht reagiert werden.',
  'Yalnız kendi notlarınızı silebilirsiniz.' => 'Sie können nur Ihre eigenen Notizen löschen.',
  'Cevap metni boş olamaz.' => 'Der Antworttext darf nicht leer sein.',
  'Bağlantı bulunamadı. Önce ayarları kaydedin.' => 'Verbindung nicht gefunden. Speichern Sie zunächst die Einstellungen.',
  'Mesaj yalnız görsel kodundan oluşuyordu; gönderilmedi.' => 'Die Nachricht bestand nur aus Bildcode; es wurde nicht gesendet.',
  'Bu kişi kara listede; mesaj gönderilmez. Kara listeden çıkarınca yeniden yazabilirsiniz.' => 'Dieser Kontakt steht auf der Sperrliste. Es werden keine Nachrichten gesendet. Entfernen Sie sie aus der Sperrliste, um erneut schreiben zu können.',
  'Mesaj kaydedilemedi.' => 'Die Nachricht konnte nicht gespeichert werden.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Dieser Kontakt schreibt von einer versteckten WhatsApp-Nummer (@lid) und Evolution API (Version %s) konnte nicht an diese Adresse senden. Aktualisieren Sie den Evolution API-Server auf 2.3 oder höher; Wenn die tatsächliche Nummer des Kontakts eintrifft, sendet das Plugin dorthin.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Dieser Kontakt schreibt von einer versteckten WhatsApp-Nummer (@lid) und Evolution API konnte nicht an diese Adresse senden. Aktualisieren Sie den Evolution API-Server auf 2.3 oder höher; Wenn die tatsächliche Nummer des Kontakts eintrifft, sendet das Plugin dorthin.',
  'WhatsApp bağlantısı yok.' => 'Keine WhatsApp-Verbindung.',
  'Bağlı ✓' => 'Verbunden ✓',
  'Bağlı değil (durum: %s). QR ile bağlayın.' => 'Nicht verbunden (Status: %s). Verbinden Sie sich mit QR.',
  'Webhook bu siteye ayarlı ✓' => 'Webhook verweist auf diese Site ✓',
  'Evolution API sürümü: %s' => 'Evolution-API-Version: %s',
  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(alt: Antworten auf Kontakte mit versteckten Nummern (@lid) schlagen möglicherweise fehl, aktualisieren Sie auf 2.3 oder höher)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'Der Webhook verweist nicht auf diese Site. Klicken Sie auf „Webhook einrichten“.',
  'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.' => 'Webhook eingerichtet ✓ Eingehende Nachrichten kommen nun hier an.',
  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => 'Aktuelle Chats werden importiert. Dies kann eine Weile dauern.',
  'Evolution\'da kayıtlı mesaj: %s' => 'In Evolution gespeicherte Nachrichten: %s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'Evolution speichert keine Nachrichten, daher können ältere Nachrichten nicht geladen werden. Setzen Sie auf dem Evolution-Server DATABASE_SAVE_DATA_NEW_MESSAGE und DATABASE_SAVE_DATA_HISTORIC auf true; Lassen Sie für ältere Konversationen „Vollständigen Verlauf synchronisieren“ in den Instanzeinstellungen aktiviert, wenn Sie die Leitung erneut mit QR verbinden.',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => '%1$s-Chats, %2$s-Nachrichten importiert ✓',
  'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.' => 'Scannen Sie diesen Code über WhatsApp › Verknüpfte Geräte › Gerät verknüpfen.',
  'Eşleştirme kodu:' => 'Pairing-Code:',
  'Bu hat zaten bağlı ✓' => 'Diese Leitung ist bereits verbunden ✓',
  'Önce ayarları kaydedin.' => 'Speichern Sie zunächst die Einstellungen.',
  'Hata:' => 'Fehler:',
  'Bu bağlantı silinsin mi? Sohbet geçmişi silinmez.' => 'Diese Verbindung löschen? Der Chatverlauf wird gespeichert.',
  'Yapay zekâya soruluyor…' => 'Die KI fragen...',
  'Çalışıyor ✓ (%2$s ms): %1$s' => 'Funktioniert ✓ (%2$s ms): %1$s',
  'Önce anahtarı ve modeli kaydedin.' => 'Speichern Sie zunächst den Schlüssel und das Modell.',
  'Bağlantılar' => 'Verbindungen',
  'Otomatik yanıtlar' => 'Automatische Antworten',
  'Yapay zekâ ve asistan' => 'KI und Assistent',
  'Sistem kontrolü' => 'Systemprüfung',
  'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.' => 'Verbinden Sie Ihre WhatsApp-Leitung, verwalten Sie automatische Antworten und Labels.',
  'Sohbetleri aç' => 'Offene Chats',
  'Ayarlar kaydedildi.' => 'Einstellungen gespeichert.',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => 'Verbindungen und Einstellungen, die das Callcenter benötigt. Der gespeicherte Status wird angezeigt. Verwenden Sie die „Test“-Schaltflächen auf jeder Registerkarte für eine Live-Überprüfung. Dieselben Prüfungen werden auch bei den anderen Plugins auf dem Systemprüfungsbildschirm des Themes angezeigt.',
  'WhatsApp hatları' => 'WhatsApp-Zeilen',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => 'Nachrichten werden über die Evolution API gesendet und empfangen. WhatsApp-Verbindungen werden in Flux Mail verwaltet; Wählen Sie hier aus, welches Sie verwenden möchten. Die URL und der API-Schlüssel bleiben dort, sodass Sie sie hier nicht aktualisieren müssen, wenn sie sich ändern.',
  'İletişim › Bağlantılar' => 'Kommunikation › Verbindungen',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => 'Nachrichten werden über die Evolution API gesendet und empfangen. Wenn in Flux Certificates ein Evolution-Anbieter eingerichtet ist, können Sie dieselbe Verbindung auswählen; Die URL und der API-Schlüssel bleiben dort.',
  'Hat ekle' => 'Zeile hinzufügen',
  'Kurulum adımları' => 'Einrichtungsschritte',
  'Hattı ekleyip kaydedin.' => 'Fügen Sie die Zeile hinzu und speichern Sie.',
  '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.' => 'Verwenden Sie „Verbindung testen“, um festzustellen, ob Evolution erreichbar ist. Wenn die Leitung nicht verknüpft ist, wählen Sie „Mit QR verbinden“ und scannen Sie sie vom Telefon aus.',
  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => 'Klicken Sie auf „Webhook einrichten“. Eingehende Nachrichten sowie Nachrichten, die vom Telefon und von Flux-Zertifikaten gesendet werden, werden dann hier live angezeigt.',
  'İsterseniz "Son sohbetleri içe aktar" ile geçmiş mesajları getirin.' => 'Optional können Sie mit „Letzte Chats importieren“ frühere Nachrichten einbinden.',
