  'Son sohbetleri içe aktar' => 'Aktuelle Chats importieren',
  'Kaydettikten sonra webhook adresi ve test düğmeleri görünür.' => 'Nach dem Speichern werden die Webhook-URL und die Testschaltflächen angezeigt.',
  'Görünüm' => 'Aussehen',
  'Panel başlığı' => 'Titel des Panels',
  'Boş bırakılırsa site adı. {brand} değişkeni de bunu kullanır.' => 'Site-Name, falls leer. Auch die Variable {brand} verwendet dies.',
  'Vurgu rengi' => 'Akzentfarbe',
  'Çalışma şekli' => 'Verhalten',
  'Sohbet açılınca karşı tarafa okundu bilgisi (mavi tik) gönder' => 'Senden Sie Lesebestätigungen (blaue Häkchen), wenn ein Chat geöffnet wird',
  'Mesajın başına temsilci adını ekle (*Ad:*)' => 'Stellen Sie den Nachrichten den Namen des Agenten (*Name:*) voran.',
  'Temsilciler yalnız kendine atanan ve atanmamış sohbetleri görsün (yöneticiler hepsini görür)' => 'Agenten sehen nur die ihnen zugewiesenen Chats und die nicht zugewiesenen Chats (Administratoren sehen alle)',
  'WhatsApp grup mesajlarını da göster' => 'Zeigen Sie auch WhatsApp-Gruppennachrichten an',
  'Yeni arayüz (deneysel): Sohbetler sayfası masaüstü ve mobil uygulamayla aynı ekranla açılır' => 'Neue Benutzeroberfläche (experimentell): Die Chats-Seite wird mit demselben Bildschirm wie die Desktop- und Mobil-App geöffnet',
  'Canlı güncelleme sıklığı (sn)' => 'Live-Update-Intervall (Sek.)',
  'Açık sekmede bu aralıkla yeni mesaj kontrol edilir (önerilen 10). Sekme arka plandayken dakikada bir, hata olursa giderek seyrekleşir.' => 'Der geöffnete Tab sucht in diesem Intervall nach neuen Nachrichten (10 empfohlen). In einer Hintergrundregisterkarte erfolgt die Überprüfung einmal pro Minute und bei Fehlern seltener.',
  'Temsilciler' => 'Agenten',
  'Bir kullanıcıya %s rolü verin; yalnız sohbet ekranını görür, ayarlara giremez. Yöneticiler her zaman erişir.' => 'Weisen Sie einem Benutzer die Rolle %s zu. Sie sehen nur den Chat-Bildschirm und können die Einstellungen nicht öffnen. Administratoren haben immer Zugriff.',
  'Yeni kullanıcı ekle' => 'Neuen Benutzer hinzufügen',
  'Veri' => 'Daten',
  'Eklenti silinirken tüm sohbetleri, mesajları ve medya dosyalarını da sil' => 'Löschen Sie auch alle Chats, Nachrichten und Mediendateien, wenn das Plugin gelöscht wird',
  'Medya dosyaları wp-content/uploads/flx-chat klasöründe, dışarıdan erişime kapalı tutulur. Site taşınırken uploads ile birlikte gider.' => 'Mediendateien werden in wp-content/uploads/flx-chat aufbewahrt und sind für den Zugriff von außen gesperrt. Sie werden mit den Uploads verschoben, wenn die Website migriert wird.',
  'Pzt' => 'Mo',
  'Sal' => 'Di',
  'Çar' => 'Mi',
  'Per' => 'Do',
  'Cum' => 'Fr',
  'Cmt' => 'Sa',
  'Paz' => 'Sonne',
  'Karşılama mesajı' => 'Willkommensnachricht',
  'Bize ilk kez yazan kişiye otomatik gönder' => 'Automatisch an Personen senden, die uns zum ersten Mal schreiben',
  'Mesai dışı yanıtı' => 'Abwesenheitsnachricht',
  'Mesai saatleri dışında gelen mesajlara otomatik yanıt ver' => 'Automatische Antwort auf Nachrichten, die außerhalb der Geschäftszeiten eingehen',
  'Mesai günleri' => 'Werktage',
  'Başlangıç' => 'Starten',
  'Bitiş' => 'Ende',
  'Aynı kişiye en fazla (saatte bir)' => 'Höchstens einmal pro Kontakt alle (Stunden)',
  'Saat dilimi: %1$s. Şu an: %2$s.' => 'Zeitzone: %1$s. Jetzt: %2$s.',
  'mesai içi' => 'innerhalb der Geschäftszeiten',
  'mesai dışı' => 'außerhalb der Geschäftszeiten',
  'Metinlerde {first_name}, {name}, {brand}, {site}, {date} değişkenleri kullanılabilir.' => 'In den Texten können die Variablen {first_name}, {name}, {brand}, {site}, {date} verwendet werden.',
  'Sohbet etiketleri' => 'Chat-Labels',
  'Sohbetleri etiketleyip listede filtreleyin (ör. Bağış, Şikâyet, Takip).' => 'Kennzeichnen Sie Chats und filtern Sie die Liste (z. B. Spende, Beschwerde, Nachverfolgung).',
  'Etiket ekle' => 'Etikett hinzufügen',
  'Etiket adı' => 'Labelname',
  'Sohbetten kayıt oluşturma' => 'Erstellen von Aufzeichnungen aus Chats',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => 'Schaltflächen im Chat-Header erstellen einen Spendendatensatz (Flux Donate) und ein Zertifikat (Flux Certificates) und eine eingehende Quittung wird einem Datensatz zugeordnet. Wenn ein Plugin nicht installiert ist, ist seine Schaltfläche ausgeblendet.',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => 'Agenten können Spendenaufzeichnungen erstellen und Belege abgleichen',
  'Temsilciler sertifika oluşturup gönderebilsin' => 'Agenten können Zertifikate erstellen und versenden',
  'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster' => 'Über dem Nachrichtenfeld werden Schnellantwortblasen angezeigt',
  'Bağış mesajları' => 'Spendennachrichten',
  'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.' => 'Fertigtexte, die beim Erstellen eines Datensatzes an die Person gesendet werden (vor dem Senden bearbeitbar). Wenn es leer bleibt, wird der Standardtext verwendet.',
  'Ödeme bekleniyor (havale sözü)' => 'Warten auf Zahlung (versprochene Überweisung)',
  'Bağış alındı' => 'Spende erhalten',
  'Dekont onaylandı' => 'Empfang bestätigt',
  'Banka bilgisi ({bank})' => 'Bankverbindung ({bank})',
  'Alıcı adı, banka, IBAN' => 'Empfängername, Bank, IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => 'Wenn leer, wird das Konto in WooCommerce › Zahlungen › Banküberweisung verwendet.',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variablen: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.',
  'Yapay zekâ bağlantısı' => 'KI-Verbindung',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => 'Schlüssel, Prompt-Caching, Ausgabenlimits und Nutzungsprotokolle stammen vom Flux AI & MCP-Plugin; Alle KI-Anfragen des Callcenters durchlaufen es. Die Modellauswahl bleibt hier; Wenn ein Feld leer ist, wird das für dieses Plugin in Flux AI ausgewählte Modell (oder die Standardeinstellung) verwendet.',
  'Flux AI ayarlarını aç' => 'Öffnen Sie die Flux AI-Einstellungen',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'AI benötigt das Flux AI & MCP Plugin. Installieren und aktivieren Sie es und geben Sie dann den OpenRouter- und/oder Anthropic-Schlüssel in Flux AI & MCP › Einstellungen ein. Bis dahin sind Vorschläge, der Assistent, das Lesen von Quittungen, Sprachnachrichten und Zusammenfassungen deaktiviert.',
  'Yaratıcılık (0–1)' => 'Kreativität (0–1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => 'Niedrigere Werte führen zu konsistenteren Antworten, höhere Werte zu freizügigeren. 0,4 empfohlen.',
  'Model (öneriler için)' => 'Modell (für Vorschläge)',
  'Asistan modeli (isteğe bağlı)' => 'Assistentenmodell (optional)',
  'Yukarıdaki model' => 'Modell oben',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => 'Es werden nur Modelle aufgeführt, die Tools unterstützen.',
  'Dekont okuma modeli (isteğe bağlı)' => 'Quittungslesemodell (optional)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => 'Wenn das ausgewählte Modell keine Bilder lesen kann, wird automatisch ein günstiges Vision-Modell verwendet.',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => 'Diesen Monat (%1$s): %2$s-Anfragen, %3$s-Tokens, etwa $%4$s.',
  'Cevap önerisi' => 'Antwortvorschläge',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => 'Über dem Nachrichtenfeld wird die nächste Nachricht aus der Konversation vorgeschlagen. Der Agent klickt auf „Senden“ oder übernimmt es mit „Bearbeiten“ in die Box. Ein Vorschlag wird niemals einzeln gesendet.',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => 'Bereiten Sie automatisch einen Vorschlag vor, wenn die letzte Nachricht von der Person kam (falls deaktiviert, fragen Sie mit der ✨-Taste nach).',
  'Kurum bilgisi ve üslup' => 'Informationen und Ton der Organisation',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => 'Z.B. Unser Verein pflanzt Setzlinge in Istanbul. Die Pflanzung erfolgt jedes Jahr zwischen November und März. Die Bescheinigung wird nach der Spende per WhatsApp verschickt. Verwenden Sie einen warmen, aber formellen Ton.',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => 'Vorschläge und der Assistent nutzen dies. Spendenarten, Preise, Bankdaten und Schnellantworten werden automatisch hinzugefügt.',
  'Öneri sağlayıcısı' => 'Vorschlagsanbieter',
  'Bağış asistanı (otomatik cevap)' => 'Spendenassistent (automatische Antworten)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => 'Wenn aktiviert, antwortet der Assistent selbst: Er begrüßt, fragt nach dem Namen, um ihn anzusprechen, sendet Spendenoptionen und Preise, sammelt optional E-Mails und „in wessen Namen“ und bittet nach jeder Änderung um eine Bestätigung. Nach der Bestätigung öffnet es in Flux Donate einen Datensatz „Warten auf Zahlung“ und sendet den Spendenlink, den Empfänger, die IBAN und die Referenz als separate Nachrichten. Wenn das Thema Spenden hinterlässt, übergibt es den Chat an das Team.',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'Das Flux Donate-Plugin ist nicht aktiv; Der Assistent kann keine Spendendatensätze erstellen.',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => 'Anleitungen, Dokumente, KI-Chats und Testchat',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => 'Schalten Sie den Spendenassistenten ein (entfernen Sie das Häkchen, um ihn überall auszuschalten)',
  'Hangi sohbetlerde cevap versin' => 'Auf welche Chats soll geantwortet werden?',
  'Tüm sohbetlerde (önerilen)' => 'In allen Chats (empfohlen)',
  'Temsilciye atanmamış sohbetlerde' => 'In Chats, die keinem Agenten zugewiesen sind',
  'Yalnız mesai saatleri dışında' => 'Nur außerhalb der Arbeitszeit',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => 'Wenn ein Agent in einem Chat schreibt (über das Panel oder das Telefon), bleibt der Assistent dort für die unten angegebene Zeit still. Verwenden Sie die Assistentenschaltfläche im Chat-Header, um es pro Chat ein- oder auszuschalten.',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => 'Testmodus: Antworten Sie nur auf die untenstehenden Nummern',
  'Test numaraları' => 'Testzahlen',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => 'Trennen Sie durch Kommas oder neue Zeilen. Wird nicht verwendet, wenn der Testmodus ausgeschaltet ist.',
  'Temsilci yazınca susma (saat)' => 'Ruhe, nachdem ein Agent schreibt (Stunden)',
  'Fiyat listesindeki adetler' => 'Mengenangaben in der Preisliste',
  'Konuşma geçmişi (saat)' => 'Gesprächsverlauf (Stunden)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => 'Bevor er antwortet, liest der Assistent alle Nachrichten aus diesem Zeitraum.',
  'Asistanın sunduğu bağış türleri' => 'Spendenarten, die der Assistent anbietet',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => 'Wenn keine ausgewählt ist, werden alle offenen Typen angeboten. Wenn in Flux Donate ein neuer Typ geöffnet wird, weiß dies auch der Assistent.',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => 'Vorabprüfung der Quittung: Wenn der Kontakt eine Quittung sendet, vergleicht die KI den Betrag, den Empfänger und die IBAN mit der Spende, teilt dem Kontakt das Ergebnis mit, hängt die Datei an den Spendendatensatz an und übergibt den Chat an das Team zur endgültigen Genehmigung (markiert ihn nicht als bezahlt).',
  'Fiyat listesinin son satırı' => 'Letzte Zeile der Preisliste',
  'Ödeme bilgileri' => 'Zahlungsdetails',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => 'Wenn der Empfänger und die IBAN leer sind, werden diejenigen in WooCommerce › Zahlungen › Banküberweisung verwendet (das bei Bestellungen angezeigte Konto). Füllen Sie diese nur aus, wenn der Assistent ein anderes Konto verwenden soll.',
  'Alıcı adı' => 'Empfängername',
  'Havale açıklaması' => 'Übertragungsbeschreibung',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => 'Variablen: {type}, {name}, {amount}, {quantity}',
  'Bağış sayfası adresi' => 'URL der Spendenseite',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => 'Der ausgewählte Typ und die ausgewählte Menge werden dem Link hinzugefügt (?flxb_opt=...&flxb_qty=...).',
  'Ödeme bilgilerinden sonraki mesaj' => 'Nachricht nach den Zahlungsdetails',
  'Bağış iptali onay sorusu' => 'Frage zur Spendenstornierung',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => 'Der Assistent storniert nur unbezahlte Spenden mit der Bestätigung der Person. Leer = Standardtext. Variablen: {bagis}, {tutar}.',
  'Günlük sınır dolunca gönderilen mesaj' => 'Nachricht wird gesendet, wenn das Tageslimit erreicht ist',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => 'Wird einmal gesendet, wenn ein Chat das Antwortlimit des Tages erreicht. Der Chat wird an das Team übergeben. Setzen Sie es über das ⋮-Menü des Chats › Assistant-Nutzung zurück.',
  'Ekibe devrederken gönderilen mesaj' => 'Nachricht wird bei Übergabe an das Team gesendet',
  'Asistan cevap veremezse giden mesaj' => 'Nachricht wird gesendet, wenn der Assistent nicht antworten kann',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => 'Wenn die KI ausfällt, das Zeitlimit erreicht ist oder die Warteschlange zu lang wird, wird diese Nachricht gesendet und der Chat an das Team übergeben; Die Person bleibt nie ohne Antwort.',
  'Bekleme mesajından önce en az (sn)' => 'Mindestwartezeit vor der/den Wartenachricht(en)',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => 'Die Haltenachricht wird erst so viele Sekunden nach der Nachricht der Person gesendet; In der Zwischenzeit versucht der Assistent es erneut.',
  'Bir cevabın en uzun süresi (sn)' => 'Längste Zeit für eine Antwort(en)',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'Hostinger kann Anfragen in ca. 60 Sekunden kürzen; 50 wird empfohlen.',
  'Devirde bildirim gidecek numaralar' => 'Nummern werden bei der Übergabe mitgeteilt',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => 'Wenn der Assistent einen Chat an das Team übergibt, wird aus derselben Leitung eine WhatsApp-Nachricht an diese Nummern gesendet: Name des Kontakts, Telefonnummer, Grund, letzte Nachrichten und Panel-Link. Trennen Sie durch Kommas oder neue Zeilen. Der Assistent spricht nicht mit diesen Nummern.',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => 'Wenn der Kontakt eine dieser Nachrichten schreibt, sendet der Assistent sofort die obige Übergabenachricht und schaltet sich in diesen Chat ein. Wenn es leer bleibt, wird die Beispielliste verwendet.',
  'Asistana ek talimatlar' => 'Zusätzliche Anweisungen für den Assistenten',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => 'Z.B. In Kocaeli werden Setzlinge gepflanzt. Sobald die Spende bestätigt ist, werden Zertifikate verschickt.',
  'Kişi mesaj istemeyince gönderilen son mesaj' => 'Letzte Nachricht, wenn sich ein Kontakt abmeldet',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => 'Wenn jemand so etwas schreibt wie „Keine Nachricht an mich senden“, sendet der Assistent diese Nachricht und setzt ihn auf die Sperrliste. Eine auf der Sperrliste stehende Person erhält keine WhatsApp, E-Mail oder SMS; Verwalten Sie die Liste unter Chats › ☰ › Blocklist.',
  'Kişi hafızası ve arka plan işleri' => 'Kontaktspeicher und Hintergrundjobs',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => 'Kontaktgedächtnis: Der Assistent merkt sich bleibende Details (Anrede, Namen von Verwandten, Nummern, Vorlieben); Abgelaufene Chats werden zusammengefasst',
  'Sohbet kaç saat sessiz kalınca özetlensin' => 'Fassen Sie einen Chat zusammen, nachdem es (Stunden) ruhig war.',
  'Aynı anda en fazla iş' => 'Maximale Jobs gleichzeitig',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => 'Wie viele Personen können gleichzeitig beantwortet werden? Die Antworten des Assistenten stehen immer an erster Stelle. Zusammenfassungen beginnen nicht, während jemand beantwortet wird oder wartet. Jeder Job verwendet einen PHP-Worker: Bleiben Sie beim Shared Hosting unter der Hälfte des gesamten Worker-Limits Ihrer Websites (z. B. 20–30 von 60 Workern).',
  'Yalnız cevaplara ayrılan işçi' => 'Für Antworten reservierte Mitarbeiter',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => 'So viele Arbeitnehmer nehmen niemals Zusammenfassungen oder Erinnerungen entgegen.',
  'Özet saatleri' => 'Zusammenfassung Stunden',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => 'Zusammenfassungen werden nur zwischen diesen Stunden ausgeführt (mit Ausnahme einer manuellen „Jetzt zusammenfassen“). Wenn beide gleich sind, jederzeit.',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => 'Wenn jemand eine Sprachnachricht sendet, wandelt der Assistent diese in Text um und antwortet (der Text erscheint auch im Panel als Systemzeile).',
  'En uzun ses (sn)' => 'Längste Sprachnachricht (Sek.)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => 'Bei längeren Nachrichten sagt der Assistent: „Die Sprachnachricht war zu lang, als dass wir sie abhören konnten.“',
  'Sesli mesaj modeli (isteğe bağlı)' => 'Sprachnachrichtenmodell (optional)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => 'Günstiges Audiomodell (Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => 'Muss ein OpenRouter-Modell sein, das Audio akzeptiert (Claude nicht). Ein OpenRouter-Schlüssel ist erforderlich.',
  'Görseller' => 'Bilder',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => 'Lassen Sie den Assistenten bei Bedarf ein Bild zeichnen (Tabelle, Bericht, Diagramm); Es geht als Bild an WhatsApp, der Text wird separat gesendet',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => 'Es wird der Bildrenderer Flux AI verwendet (Flux AI & MCP › Einstellungen › Bilder).',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => 'Kein Bildrenderer auf dem Server: Geben Sie eine Gotenberg-Adresse in Flux AI & MCP › Einstellungen › Bilder ein oder installieren Sie Imagick (SVG). Bis dahin zeichnet der Assistent keine Bilder.',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => 'Funktioniert, sobald Flux AI 0.2.0 oder höher installiert ist.',
  'Başkası adına bağış' => 'Spende im Namen einer Person',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => 'Wenn die Spende auf den Namen einer anderen Person lautet und deren Nummer angegeben wurde (Kontaktkarte oder getippte Nummer), senden Sie die Bescheinigung auch an diese Nummer auf WhatsApp, sobald die Zahlung genehmigt wurde',
  'Sertifikadan önce giden mesaj' => 'Vor dem Zertifikat gesendete Nachricht',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => 'Anschließend wird die WhatsApp-Zertifikatsnachricht von Flux Certificates versendet. Variablen: {ad}, {bagisci}, {bagis}, {brand}.',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => 'Wenn eine Person danach fragt, richtet der Assistent eine Erinnerung ein (z. B. „erinnere mich jeden Monat an das Pflanzen eines Setzlings“, „sende mir jeden Monat deine neuesten Projekte“, „frage mich jeden Monat nach einem Setzling“); Wenn es fällig ist, schreibt und sendet der Assistent die Nachricht',
  'Saat söylenmezse' => 'Wenn keine Zeit gegeben ist',
  'Kişi başına en fazla' => 'Höchstens pro Person',
  'Personel (Flux Roles)' => 'Mitarbeiter (Flux-Rollen)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => 'Funktioniert, sobald Flux Roles 1.1.0 installiert ist: Benutzer, deren Nummer in Profil › WhatsApp-Nummer festgelegt ist, erhalten zusätzliche Hilfstools basierend auf ihren Berechtigungen.',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => 'Geben Sie Mitarbeitern mit Erlaubnis zusätzliche Hilfstools (Spende im Namen einer Person mit Zahlungslink, meine Spender, allgemeiner Bericht).',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => 'Benachrichtigen Sie die Mitarbeiter über WhatsApp, wenn eine von ihnen empfohlene Spende bezahlt oder storniert wird',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => 'Erste Nachricht an den Spender für eine Spende, geöffnet durch Mitarbeiter',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => 'Hallo {ad}🌱 Deine {bagis}-Spendenanfrage über {personel} ist eingegangen. Sie können mit den untenstehenden Angaben bezahlen.',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Es folgen der Zahlungslink und die Bankdaten. Variablen: {ad}, {adsoyad}, {personel}, {bagis}.',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => 'Wenn eine von einem Mitarbeiter empfohlene Spende ausgezahlt und die entsprechenden Bescheinigungen ausgestellt werden, senden Sie diese ebenfalls über WhatsApp an den Mitarbeiter (genau wie den Spender).',
  'Personele sertifikadan önce giden mesaj' => 'Nachricht, die vor der Urkunde an den Mitarbeiter gesendet wird',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variablen: {ad}, {bagisci}, {bagis}, {no}, {brand}.',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => 'Wie oft können Mitarbeiter eine Spendenbescheinigung erneut senden?',
  'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.' => 'Der Assistent listet die Empfänger auf und bittet vor dem Senden um eine Bestätigung. 0: aus.',
  'Kayıt sorgusunda kod doğrulama' => 'Codeüberprüfung für Datensatzsuche',
  'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir' => 'Wenn eine Person nach ihren Unterlagen fragt und ihre Nummer verborgen ist (oder sie mit einer anderen Nummer/E-Mail-Adresse gespendet hat), senden Sie einen Code an die angegebene Nummer oder E-Mail-Adresse. Nach der Überprüfung werden auch die Datensätze angezeigt',
  'Kod geçerliliği (dk)' => 'Codegültigkeit (min.)',
  'En fazla başarısız deneme' => 'Maximale Fehlversuche',
  'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.' => 'Es zählen Codes, die nicht versendet werden konnten, falsche Codes und abgelaufene Codes. Bei Erreichen des Limits erhält die Person die folgende Nachricht und das Team wird benachrichtigt; Der Assistent beantwortet weiterhin andere Fragen, teilt jedoch 24 Stunden lang keine Datensatzdetails mit.',
  'Telefona kod' => 'Code zum Telefonieren',
  'WhatsApp, gitmezse SMS' => 'WhatsApp, SMS, wenn es fehlschlägt',
  'Yalnız WhatsApp' => 'Nur WhatsApp',
  'Yalnız SMS' => 'Nur SMS',
  'SMS, Flux Mail\'te SMS bağlantısı (ör. Netgsm) varsa kullanılır.' => 'SMS wird verwendet, wenn Flux Mail über eine SMS-Verbindung verfügt (z. B. Netgsm).',
  'Doğrulama yapılamazsa giden mesaj' => 'Meldung, wenn die Überprüfung fehlschlägt',
  'WhatsApp/SMS kod mesajı' => 'WhatsApp/SMS-Codenachricht',
  'Boşsa varsayılan metin. Değişkenler: {kod}, {dk}, {marka}. E-posta metni Flux Mail › E-posta şablonları\'ndan değişir.' => 'Standardtext, falls leer. Variablen: {kod}, {dk}, {marka}. Der E-Mail-Text wird in Flux Mail › E-Mail-Vorlagen bearbeitet.',
  'Sitedeki içerikler' => 'Inhalt der Website',
  'Asistan sitede yayında olan içeriklerde arama yapabilsin (ör. "fidan dikimi geçen bir gönderiniz var mı")' => 'Lassen Sie den Assistenten nach veröffentlichten Inhalten der Website suchen (z. B. „Haben Sie einen Beitrag zum Thema Baumpflanzung“)?',
  'Aranacak içerik türleri' => 'Zu durchsuchende Inhaltstypen',
  'Yalnız yayında ve şifresiz içerikler döner. Taslak, özel ve şifreli içerik hiçbir zaman gösterilmez.' => 'Es werden nur veröffentlichte Inhalte ohne Passwort zurückgegeben. Entwürfe, private und passwortgeschützte Inhalte werden niemals angezeigt.',
  'Hiç paylaşılmayacak kategori ve etiketler' => 'Kategorien und Tags dürfen niemals geteilt werden',
  'ör. kurumsal-teklifler, ic-duyuru' => 'z.B. Firmenangebote, interne Bekanntmachung',
  'Ad ya da kısa ad, virgülle. Tek bir içeriği gizlemek için düzenleme ekranındaki "Asistan bu içeriği kişilerle paylaşmasın" kutusunu işaretleyin.' => 'Name oder Slug, durch Komma getrennt. Um ein einzelnes Element auszublenden, aktivieren Sie auf dem Bearbeitungsbildschirm die Option „Diesen Inhalt nicht vom Assistenten teilen lassen“.',
  'Ekip grubu' => 'Teamgruppe',
  'WhatsApp grubu' => 'WhatsApp-Gruppe',
  '— Seçilmedi —' => '— Nicht ausgewählt —',
  'Hattın üye olduğu gruplar. Yeni açtığınız grup görünmüyorsa' => 'Gruppen, denen die Linie angehört. Wenn eine Gruppe, die Sie gerade erstellt haben, fehlt,',
  'listeyi yenileyin' => 'Aktualisieren Sie die Liste',
  'Kişilerden gelen mesajları ve verilen cevapları (asistan, ekip, otomatik) bu gruba yaz' => 'Veröffentlichen Sie eingehende Nachrichten und Antworten (Assistent, Team, automatisch) in dieser Gruppe',
  'Devir bildirimini numaralara ayrı ayrı değil bu gruba gönder; yukarıdaki numaralar mesajda etiketlenir' => 'Senden Sie Übergabebenachrichtigungen an diese Gruppe statt an jede einzelne Nummer. Die oben genannten Nummern werden in der Nachricht erwähnt',
  'Gruba son gönderim başarısız: ' => 'Der letzte Beitrag in der Gruppe ist fehlgeschlagen:',
  'Fiyat listesi önizlemesi' => 'Vorschau der Preisliste',
  'Asistanın çalışması için önce yapay zekâ anahtarı ve model girin.' => 'Geben Sie zunächst einen KI-Schlüssel und ein Modell ein, damit der Assistent arbeiten kann.',
  'Asistan şu an konuşmaz: ' => 'Der Assistent antwortet derzeit nicht:',
  'WhatsApp asistanı' => 'WhatsApp-Assistent',
  'Asistan bu içeriği kişilerle paylaşmasın' => 'Lassen Sie nicht zu, dass der Assistent diesen Inhalt teilt',
  'Personel %1$s düzeltti; yerine #%2$d açıldı.' => 'Korrigiert durch Mitarbeiter %1$s; Stattdessen wurde #%2$d geöffnet.',
  'Bağış #%1$d iptal edildi, yerine #%2$d açıldı.' => 'Die Spende #%1$d wurde abgebrochen und stattdessen #%2$d eröffnet.',
  'Personel %s WhatsApp asistanıyla oluşturdu.' => 'Erstellt vom Mitarbeiter %s über den WhatsApp-Assistenten.',
  'Personel %1$s aracılığıyla bağış kaydı açıldı: %2$s (#%3$d)' => 'Spende über Mitarbeiter eröffnet %1$s: %2$s(#%3$d)',
  'Sertifikanız 🌱' => 'Dein Zertifikat 🌱',
  'Personel %1$s sertifikayı WhatsApp\'tan yeniden gönderdi: %2$s' => 'Mitarbeiter %1$s hat das Zertifikat erneut auf WhatsApp gesendet: %2$s',
  '✅ Bağışçınız ödedi: *%1$s* · %2$s #%3$d' => '✅ Ihr Spender hat Folgendes bezahlt: *%1$s* ·%2$s#%3$d',
  '❌ Bağış iptal edildi: *%1$s* · %2$s #%3$d' => '❌ Spende storniert: *%1$s* ·%2$s#%3$d',
  'Çıkartma' => 'Aufkleber',
  'Anket' => 'Umfrage',
  'Desteklenmeyen mesaj' => 'Nicht unterstützte Nachricht',
  '{a} satır eklendi, {d} satır çıkarıldı' => '{a}-Zeilen hinzugefügt, {d}-Zeilen entfernt',
  'Yapay zekâ anahtarı ya da modeli girilmemiş.' => 'Es wurde kein KI-Schlüssel oder Modell eingegeben.',
  'Asistan kapalı; gelen mesajlara cevap vermiyor.' => 'Der Assistent ist ausgeschaltet und antwortet nicht auf eingehende Nachrichten.',
  'Test modu açık: asistan yalnız test numaralarına cevap veriyor.' => 'Der Testmodus ist aktiviert: Der Assistent antwortet nur auf Testnummern.',
  'Asistanın çalışma özeti' => 'Zusammenfassung der Assistentenaktivitäten',
  'Detayı gizle' => 'Details ausblenden',
  'Detay' => 'Details',
  'Harcama (USD)' => 'Ausgaben (USD)',
  'Cevaplanan soru' => 'Fragen beantwortet',
  'Cevap verilen kişi' => 'Die Leute antworteten',
  'Bağışa yönlendirilen kişi' => 'Menschen werden zum Spenden aufgefordert',
  'Açılan bağış kaydı' => 'Spendenunterlagen erstellt',
  'Onaylanan bağış · {a}' => 'Bestätigte Spenden ·{a}',
  'Okunan dekont · ✓{a} ✕{b}' => 'Belege gelesen · ✓{a}✕{b}',
  'Ekibe devir' => 'Übergabe an das Team',
  'Hafıza token · {p} kişi' => 'Speichertoken ·{p}-Kontakte',
  'Mesaj istemedi (kara liste)' => 'Abgemeldet (Sperrliste)',
  'Gönderilen hatırlatıcı' => 'Erinnerungen gesendet',
  'Gönderilen kod · e-posta {e} · WhatsApp {w} · SMS {s}' => 'Gesendete Codes · E-Mail {e}· WhatsApp {w}· SMS {s}',
  'Doğrulanan · telefon {p} · e-posta {e}' => 'Verifiziert · Telefon {p}· E-Mail {e}',
  'Kod sorunu · yanlış {w} · süresi doldu {x} · gitmedi {f}' => 'Codeprobleme · falsch {w}· abgelaufen {x}· nicht geliefert {f}',
  'Doğrulanamadı, ekibe bildirildi' => 'Nicht verifiziert, Team benachrichtigt',
  'Yeniden gönderilen sertifika' => 'Zertifikate erneut gesendet',
  'Asistanın iptal ettiği bağış' => 'Spenden wurden vom Assistenten storniert',
  'Yeniden gönderilen ödeme linki' => 'Zahlungslinks erneut gesendet',
  'Token: {i} giriş / {o} çıkış · {c} istek · {m} mesaj gönderildi' => 'Tokens: {i}-Eingabe /{o}-Ausgabe ·{c}-Anfragen ·{m}-Nachrichten gesendet',
  '{n} bağış ödeme bekliyor' => '{n} Spenden warten auf Zahlung',
