  '{n} sohbet özetlendi' => '{n}-Chats zusammengefasst',
  'Sayaçlar {d} tarihinden beri' => 'Zähler seit {d}',
  '30 sn\'de bir yenilenir' => 'Wird alle 30 s aktualisiert',
  'Modeller' => 'Modelle',
  'En çok hafızası olan kişiler' => 'Kontakte mit dem meisten Speicher',
  'Token' => 'Token',
  'Günlük' => 'Täglich',
  'Bu aralıkta kayıt yok.' => 'Keine Datensätze in diesem Bereich.',
  'Cevap' => 'Antworten',
  'Devir' => 'Übergabe',
  'Yalnız gerçek sohbetler sayılır; test sohbeti ve benchmark hariç. "Onaylanan" asistanın açtığı ve ödendi işaretlenen bağışlardır.' => 'Es werden nur echte Chats gezählt; Test-Chat und Benchmark sind ausgeschlossen. „Bestätigt“ bedeutet vom Assistenten erstellte und als bezahlt markierte Spenden.',
  'Asistanın yazdığı sohbet' => 'Chats, in denen der Assistent geschrieben hat',
  'Ekipte / beklemede' => 'Mit dem Team / pausiert',
  'Bağış kaydı açılan' => 'Spendendatensatz erstellt',
  'Asistan henüz bir sohbete cevap vermedi.' => 'Der Assistent hat noch auf keinen Chat geantwortet.',
  'Daha fazla' => 'Mehr laden',
  'Sohbet kapalı' => 'Chat geschlossen',
  'Hitap: {h}' => 'Adresse: {h}',
  '{n} asistan mesajı' => '{n}-Assistentenmeldungen',
  'Bağış #{id}' => 'Spende #{id}',
  'Sürüm {id}' => 'Version {id}',
  'Değişiklik notu (ör. Kurban sorusu eklendi)' => 'Notiz ändern (z. B. Opferfrage hinzugefügt)',
  'Asistan talimatı' => 'Anweisungen des Assistenten',
  'Asistanın nasıl konuşacağını ve akışı anlatan ana metin. Fiyatlar, bağış türleri, banka bilgisi ve kişinin bilinen bilgileri her cevapta otomatik eklenir. {brand} kurum adına, {{belge:kisa-ad}} o belgenin içeriğine dönüşür.' => 'Der Haupttext beschreibt, wie der Assistent spricht und wie er abläuft. Preise, Spendenarten, Bankdaten und die Informationen zum Kontakt werden bei jeder Antwort automatisch hinzugefügt.{brand} wird zum Namen der Organisation und {{belge:kisa-ad}} wird zum Inhalt dieses Dokuments.',
  'Hemen yayına al' => 'Jetzt veröffentlichen',
  'Yeni sürüm kaydedildi' => 'Neue Version gespeichert',
  'Yeni sürüm olarak kaydet' => 'Als neue Version speichern',
  'Modele giden tam metni gör' => 'Zeigt den vollständigen Text an, der an das Modell gesendet wurde',
  'Kaydedilmemiş metin' => 'Nicht gespeicherter Text',
  'Bu metinle test et' => 'Testen Sie mit diesem Text',
  'Sürümler' => 'Versionen',
  'Yayında' => 'Lebe',
  'Eklentiyle gelen metin' => 'Text, der mit dem Plugin geliefert wird',
  'Fark: yayındaki → {v}' => 'Diff: live →{v}',
  'Farkı gör' => 'Diff. anzeigen',
  'Test et' => 'Testen',
  'Yayına alındı' => 'Veröffentlicht',
  'Yayına al' => 'Veröffentlichen',
  'Sunucunun gönderdiği hazır mesajlar' => 'Vom Server gesendete vorgefertigte Nachrichten',
  'Bu mesajları model yazmaz; ayarlardaki bilgilerden üretilir.' => 'Das Modell schreibt diese nicht; Sie werden aus Ihren Einstellungen generiert.',
  'Ayarlarda değiştir' => 'Änderung der Einstellungen',
  '(boş)' => '(leer)',
  'Modele giden tam metin (örnek sohbet)' => 'Volltext an das Model gesendet (Beispiel-Chat)',
  'Ek belgeler' => 'Zusätzliche Dokumente',
  'Sık sorulan sorular, kampanya, dikim yerleri gibi bilgileri ayrı belgeler olarak ekleyin. Talimatta {{belge:kisa-ad}} yazarsanız belge oraya konur. "Gerektiğinde okur" seçilen belgeyi asistan yalnız konu açılınca okur; uzun belgeler için daha az maliyetlidir.' => 'Fügen Sie FAQs, Kampagnen, Pflanzorte und ähnliche Informationen als separate Dokumente hinzu. Wenn Sie in der Anleitung {{belge:kisa-ad}} schreiben, wird das Dokument dort abgelegt. Ein Dokument, das auf „Bei Bedarf lesen“ eingestellt ist, wird nur gelesen, wenn das Thema auftaucht, was bei langen Dokumenten weniger kostet.',
  'Yeni belge' => 'Neues Dokument',
  'Henüz belge yok.' => 'Noch keine Dokumente.',
  'Talimatta kullanmak için kopyalayın' => 'Kopieren Sie es, um es in der Anleitung zu verwenden',
  '“{t}” belgesi silinsin mi?' => 'Dokument „{t}“ löschen?',
  'otomatik' => 'automatisch',
  'Belgeyi düzenle' => 'Dokument bearbeiten',
  'Kısa ad' => 'Kurzname',
  'İçerik (Markdown)' => 'Inhalt (Markdown)',
  'Belge kaydedildi' => 'Dokument gespeichert',
  'giriş' => 'in',
  'çıkış' => 'raus',
  'önbellek {r} okundu, {w} yazıldı' => 'Cache {r} gelesen, {w} geschrieben',
