  'Bu oturumdan sonra yayındaki talimat değişti; yeni bir oturum açmanız önerilir.' => 'Die Live-Anweisungen änderten sich nach dieser Sitzung; Es wird empfohlen, eine neue Sitzung zu beginnen.',
  'Neyi değiştirmek istediğinizi yazın. Bir kişinin ya da numaranın sohbetinden bahsederseniz yapay zekâ sohbeti bulur, okumak için sizden izin ister, talimatı günceller ve sağdaki test sohbetinde kendisi dener. Yayına almak sizin onayınızla olur.' => 'Schreiben Sie, was Sie ändern möchten. Wenn Sie den Chat einer Person oder einer Nummer erwähnen, findet die KI ihn, bittet Sie um Erlaubnis, ihn lesen zu dürfen, aktualisiert die Anweisungen und probiert sie selbst im Test-Chat rechts aus. Für die Veröffentlichung ist Ihre Zustimmung erforderlich.',
