  'Şimdi tara' => 'Jetzt scannen',
  'Önce yazan kişilere cevap verilir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. {h} saat sessiz kalan sohbetler yalnız {w} arasında özetlenir. Aynı anda en fazla {m} iş çalışır, {r} işçi yalnız cevaplara ayrılır (benchmark bir iş sayılır). 5 sn\'de bir yenilenir.' => 'Wer schreibt, dem wird zuerst geantwortet; Es wird keine Zusammenfassung gestartet, während jemand beantwortet wird oder wartet. Chats, die für {h} Stunden ruhig waren, werden nur zwischen {w} zusammengefasst. Bei den meisten {m}-Jobs, die gleichzeitig ausgeführt werden, sind {r}-Worker für Antworten reserviert (ein Benchmark zählt als einer). Wird alle 5 s aktualisiert.',
