  'Henüz çalıştırma yok; varsayılan tahmin: müşteri mesajı başına ~{i} giriş / {o} çıkış token.' => 'Noch keine Läufe; Standardschätzung: ~{i} Eingabe-/{o} Ausgabe-Token pro Spendernachricht.',
  'Tahmin ücret limitini aşıyor; limit dolunca çalıştırma durur.' => 'Der Kostenvoranschlag überschreitet die Kostengrenze; Der Lauf stoppt, wenn das Limit erreicht ist.',
  'Yeni çalıştırma' => 'Neuer Lauf',
  'Senaryolar test sohbetindeki gibi oynatılır: WhatsApp\'a mesaj gitmez, kayıt açılmaz. Model gerçekten çağrılır; ücret yapay zekâ hesabınızdan (OpenRouter ya da Anthropic) düşer ve limit dolunca çalıştırma durur.' => 'Es werden Szenarien wie im Testchat abgespielt: Es wird keine WhatsApp-Nachricht gesendet und kein Datensatz erstellt. Das Modell heißt wirklich; Die Kosten werden Ihrem AI-Konto (OpenRouter oder Anthropic) belastet und der Lauf stoppt, wenn das Limit erreicht ist.',
