  'Mesajlar (sırayla)' => 'Nachrichten (in der Reihenfolge)',
  '{tur}, {birim} ve {brand} kullanılabilir. Yalnız müşteri mesajı varsa asistan her birine sırayla cevap verir. Asistan mesajı eklerseniz devam senaryosu olur: yazılan geçmiş hazır verilir, asistan yalnız en sondaki müşteri mesajına cevap verir.' => 'Es können {tur}, {birim} und {brand} verwendet werden. Liegen nur Kundennachrichten vor, antwortet der Assistent der Reihe nach. Wenn Sie Assistentennachrichten hinzufügen, entsteht ein Fortsetzungsszenario: Der geschriebene Verlauf wird unverändert angezeigt und der Assistent antwortet nur auf die letzte Kundennachricht.',
  'Ör. payment_info, cancel_donation, receipt_check. Bu sitede kapalı araç bakılmaz.' => 'Z.B. payment_info, cancel_donation, quitt_check. Auf dieser Website deaktivierte Tools werden nicht überprüft.',
