  'Senaryo test sohbetindeki gibi izole oynar; burada seçilenler yalnız bu testte vardır. Müşteri mesajında {kod} test panelindeki doğrulama kodu olur.' => 'Das Szenario läuft wie der Testchat isoliert ab; Was Sie hier auswählen, existiert nur in diesem Test. In einer Kundennachricht wird {kod} zum Verifizierungscode des Testpanels.',
  'Sonda durum' => 'Endzustand',
