  'Çağrı Merkezi · WhatsApp' => 'Callcenter · WhatsApp',
  'Çağrı Merkezi · Yapay zekâ' => 'Callcenter · KI',
  'Veritabanı tabloları' => 'Datenbanktabellen',
  'Eksik tablo: %s. Eklentiyi devre dışı bırakıp yeniden etkinleştirin.' => 'Fehlende Tabelle: %s. Deaktivieren Sie das Plugin und aktivieren Sie es erneut.',
  'Tablolar hazır (şema %s).' => 'Tabellen bereit (Schema %s).',
  'Şema güncellemesi bekliyor; yönetim panelinde bir sayfa açınca tamamlanır.' => 'Schemaaktualisierung steht aus; Es wird abgeschlossen, wenn Sie eine Seite im Admin-Bereich öffnen.',
  'Medya klasörü' => 'Medienordner',
  'uploads/flx-chat klasörüne yazılamıyor; gelen fotoğraf, ses ve belgeler kaydedilemez. Klasör izinlerini kontrol edin.' => 'Kann nicht in Uploads/flx-chat schreiben; Eingehende Fotos, Sprachnotizen und Dokumente können nicht gespeichert werden. Überprüfen Sie die Ordnerberechtigungen.',
  'Klasör koruması (.htaccess) yok; ilk medya kaydında oluşturulur.' => 'Ordnerschutz (.htaccess) fehlt; es wird mit dem ersten gespeicherten Medium erstellt.',
  'Yazılabilir ve dışarıya kapalı.' => 'Beschreibbar und für die Öffentlichkeit geschlossen.',
  'Var.' => 'Verfügbar.',
  'Yok; asistan cevap hazırlarken "yazıyor…" göstergesi yalnız kısa süre görünür.' => 'Fehlt; Während der Assistent eine Antwort vorbereitet, wird die Anzeige „Tippen...“ nur kurz angezeigt.',
  'Temsilci rolündeki kullanıcı sayısı: %d.' => 'Benutzer mit der Agentenrolle: %d.',
  'Temsilci rolünde kullanıcı yok; şimdilik yalnız yöneticiler kullanabilir.' => 'Kein Benutzer hat die Agentenrolle; Derzeit können nur Administratoren es verwenden.',
  'Panelin canlı güncellemesi' => 'Live-Panel-Updates',
  'Son güncelleme isteği %1$s. Panel açıkken %2$d sn\'de bir yeni mesaj sorulur (arka plandaki sekmede 60 sn).' => 'Letzte Aktualisierungsanforderung %1$s. Während das Panel geöffnet ist, prüft es alle %2$d s (60 s in einer Hintergrundregisterkarte) auf neue Nachrichten.',
  'Sohbet ekranı henüz hiç açılmadı.' => 'Der Chat-Bildschirm wurde noch nicht geöffnet.',
  'WhatsApp hattı' => 'WhatsApp-Leitung',
  'Hiç hat eklenmemiş.' => 'Keine Zeile hinzugefügt.',
  '%s: bağlantı bilgisi' => '%s: Verbindungsdetails',
  'Flux Mail bağlantısı kullanılıyor: %s.' => 'Verwenden der Flux Mail-Verbindung: %s.',
  'Hâlâ Flux Certificates\'daki eski sağlayıcı kullanılıyor; bağlantıyı Flux Mail\'e taşıyıp burada seçin.' => 'Ich verwende immer noch den alten Anbieter für Flux-Zertifikate. Verschieben Sie die Verbindung zu Flux Mail und wählen Sie sie hier aus.',
  'Flux Certificates\'daki Evolution sağlayıcısı kullanılıyor.' => 'Verwendung des Evolution-Anbieters von Flux Certificates.',
  'API adresi, key ve instance bu eklentide girilmiş.' => 'In diesem Plugin werden API-URL, Schlüssel und Instanz eingetragen.',
  '%s: hat durumu' => '%s: Leitungsstatus',
  'Telefon bağlı (son bilgi %s).' => 'Telefon verbunden (zuletzt gesehen %s).',
  'Henüz denenmedi. "Bağlantıyı test et" düğmesine basın.' => 'Noch nicht getestet. Drücken Sie „Verbindung testen“.',
  'Telefon bağlı değil (durum: %1$s, %2$s). "QR ile bağla" ile yeniden bağlayın.' => 'Telefon nicht verbunden (Status: %1$s, %2$s). Stellen Sie die Verbindung mit „Mit QR verbinden“ wieder her.',
  '%s: Evolution API sürümü' => '%s: Evolution-API-Version',
  'Evolution API %s kullanılıyor. Gizli numaralı (@lid) kişilere cevap gitmeyebilir; sunucuyu 2.3 veya üstüne güncelleyin.' => 'Die Evolution API %s wird verwendet. Antworten auf Kontakte mit versteckten Nummern (@lid) schlagen möglicherweise fehl; Aktualisieren Sie den Server auf 2.3 oder höher.',
  '%s: webhook (gelen mesajlar)' => '%s: Webhook (eingehende Nachrichten)',
  'Evolution\'dan hiç olay gelmedi; gelen mesajlar panele düşmez. "Webhook\'u kur" düğmesine basın.' => 'Von Evolution sind keine Ereignisse eingetroffen; Eingehende Nachrichten werden nicht im Panel angezeigt. Klicken Sie auf „Webhook einrichten“.',
  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => 'Das letzte Ereignis ist eingetroffen %s. Möglicherweise ist die Leitung einfach nur ruhig; Senden Sie sich zur Sicherheit eine Nachricht oder richten Sie den Webhook erneut ein.',
  'Son olay %s geldi.' => 'Das letzte Ereignis ist eingetroffen %s.',
  'Flux Mail entegrasyonu' => 'Flux Mail-Integration',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => 'Aktiv: WhatsApp-Verbindungen werden aus Kommunikation › Verbindungen übernommen.',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux Mail ist nicht aktiv; Verbindungen werden von Flux-Zertifikaten oder von diesem Plugin übernommen.',
  'Flux Certificates entegrasyonu' => 'Integration von Flux-Zertifikaten',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => 'Aktiv: Zertifikate können aus Chats erstellt und versendet werden.',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'Flux-Zertifikate sind nicht aktiv; Zertifikataktionen in Chats sind deaktiviert.',
  'Flux Donate entegrasyonu' => 'Flux Donate-Integration',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => 'Aktiv: Spendenaufzeichnungen, Quittungsabgleich und der Assistent sind über Chats verfügbar.',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => 'Flux Donate ist nicht aktiv; Spendenaufzeichnungen, Belegabgleich und der Spendenassistent sind deaktiviert.',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'Das Flux AI & MCP-Plugin ist nicht installiert; KI-Funktionen (Vorschläge, Assistent, Vorlesen von Belegen, Sprachnachrichten, Zusammenfassungen) sind deaktiviert. Installieren Sie Flux AI und geben Sie dort den Schlüssel ein.',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'In Flux AI wurde kein Schlüssel eingegeben; Nachrichtenvorschläge und der Assistent sind ausgeschaltet.',
  'Anahtar var ama model seçilmemiş.' => 'Schlüssel gespeichert, aber kein Modell ausgewählt.',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => 'Für das ausgewählte Modell (%s) wurde in Flux AI kein Providerschlüssel eingetragen.',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => 'Schlüssel gespeichert, Modell: %s. Nutzen Sie „Verbindung testen“ für einen Live-Check.',
  'Bağış asistanı' => 'Spendenassistent',
  'Kapalı.' => 'Aus.',
  'Yapay zekâ anahtarı veya modeli eksik.' => 'KI-Schlüssel oder Modell fehlt.',
  'Açık ama konuşmuyor: ' => 'An, antwortet aber nicht:',
  'Açık. Sunulan bağış türleri: %s.' => 'Auf. Angebotene Spendenarten: %s.',
  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%s unterstützt keine Tools; Wählen Sie ein werkzeugfähiges Modell für den Assistenten.',
  'Dekont okuma modeli' => 'Modell zum Lesen von Quittungen',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => '%s kann keine Bilder lesen; Die Quittungsvorprüfung funktioniert nicht. Wählen Sie ein bildfähiges Beleglesemodell.',
  'Asistanın ödeme bilgileri' => 'Zahlungsdetails des Assistenten',
  'Alıcı adı ve IBAN tanımlı.' => 'Empfängername und IBAN eingestellt.',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => 'Empfängername oder IBAN fehlen; Bankdaten können nach Bestätigung nicht übermittelt werden.',
  'Bağış sayfası linki' => 'Link zur Spendenseite',
  'Bağış sayfası bulunamadı; asistan link göndermez.' => 'Spendenseite nicht gefunden; Der Assistent sendet keinen Link.',
  'Arka plan istekleri' => 'Hintergrundanfragen',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => 'Die Site konnte keine Hintergrundanforderung an sich selbst senden (%1$s: %2$s). Antworten in der Warteschlange und der Benchmark bewegen sich möglicherweise langsam; Möglicherweise blockiert ein Sicherheits-Plugin oder die Server-Firewall /wp-json/flx-chat/-Anfragen.',
  'hata' => 'Fehler',
  'uyarı' => 'Warnung',
  'tamam' => 'ok',
  '{marka} doğrulama kodunuz: {kod}' => 'Ihr {marka}-Bestätigungscode: {kod}',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => 'Der Code ist für {dk}-Minuten gültig. Geben Sie es in Ihren WhatsApp-Chat mit uns ein. Wenn Sie nicht danach gefragt haben, ignorieren Sie diese Nachricht.',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => 'Etwas ist schief gelaufen; Unser Team wird sich so schnell wie möglich mit Ihnen in Verbindung setzen 🌱 In der Zwischenzeit können Sie gerne weitere Fragen stellen.',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => 'Überprüfungsversuch fehlgeschlagen (%1$d/%2$d): %3$s',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => 'Die Person wollte ihre Unterlagen einsehen, konnte aber nicht verifiziert werden; Jemand aus dem Team sollte sich melden',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => 'E-Mail konnte nicht gesendet werden (überprüfen Sie die Flux Mail › SMTP-Einstellungen)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => 'Der Assistent hat einen Bestätigungscode für %1$s(%2$s) gesendet.',
  'kodun süresi doldu' => 'Code abgelaufen',
  'yanlış kod' => 'falscher Code',
  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => 'Die Person hat den Code für %s überprüft; Es wird zu ihren Datensatzsuchen hinzugefügt.',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => 'Claude-Modelle können keine Audiodaten lesen. Wählen Sie unter Einstellungen › AI › Sprachnachrichtenmodell ein audiofähiges OpenRouter-Modell aus.',
  'Ses metne çevrilemedi.' => 'Der Ton konnte nicht transkribiert werden.',
  'Ses dosyası okunamadı.' => 'Die Audiodatei konnte nicht gelesen werden.',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => 'Sprachnachricht (%1$s) transkribiert: %2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => 'Sprachnachricht (%1$s) konnte nicht verarbeitet werden: %2$s',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => 'Diese Aktion ist in einer offiziellen WhatsApp Cloud-API-Linie nicht verfügbar.',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'WhatsApp 24-Stunden-Regel: Der Kontakt hat in den letzten 24 Stunden nicht geschrieben, daher sendet die Cloud API keine Freiformnachricht; Es kann nur eine genehmigte Vorlage gesendet werden. Versuchen Sie es noch einmal, sobald sie schreiben.',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'Eine Cloud-API-Zeile benötigt Flux Mail 1.10.0 oder höher.',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'Die Cloud API kann nicht an diese Adresse senden (versteckte Nummer oder Gruppe).',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => 'Das Cloud-API-Konto konnte nicht erreicht werden (Link › Verbindungen).',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'Eine Cloud-API-Zeile hat keinen QR-Code; Das Konto wird unter „Verbindungen“ eingerichtet.',
  'Dosya hazırlanamadı.' => 'Die Datei konnte nicht vorbereitet werden.',
  'Flux AI görsel desteği yok.' => 'Flux AI bietet keine Bildunterstützung.',
  'Görsel çevrilemedi.' => 'Das Bild konnte nicht gerendert werden.',
  'Asistanın görseli gönderilemedi: ' => 'Das Bild des Assistenten konnte nicht gesendet werden:',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => 'Hallo {first_name}, wir haben Ihren Spendendatensatz erstellt: {donation}, insgesamt {amount}.{bank} Nach der Bezahlung können Sie hier die Quittung senden. Danke schön.',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => 'Hallo {first_name}, Ihre Spende wurde erfasst: {donation}, insgesamt {amount}.' . chr(10) . '' . chr(10) . 'Vielen Dank für Ihre Unterstützung.',
  'Bu senaryoyu oynatacak eklenti kapalı.' => 'Das Plugin, das dieses Szenario ausführen würde, ist inaktiv.',
  'Bu kullanıcının personel araçları yetkisi yok.' => 'Dieser Benutzer darf die Mitarbeitertools nicht verwenden.',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => '%1$s hat diesen Chat mit dem Mitarbeiter %2$s verknüpft',
  '%s sohbetin personel bağlantısını kaldırdı' => '%s hat den Mitarbeiterlink dieses Chats entfernt',
  'Sohbet personele bağlandı' => 'Chat mit Mitarbeiter verknüpft',
  'Personel bağlantısı kaldırıldı' => 'Mitarbeiterlink entfernt',
  '— Personel değil —' => '– Kein Personal –',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'WhatsApp verbirgt die Nummer dieser Person, sodass der Assistent das Personal nicht anhand der Nummer erkennen kann. Wenn diese Person zu Ihrem Team gehört, verlinken Sie sie hier und der Assistent öffnet die Mitarbeitertools.',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => 'Der Assistent erkennt Mitarbeiter anhand der Nummer in ihrem Flux Roles-Profil. Wenn die Nummer nicht übereinstimmt, können Sie sie hier verlinken; Bei einem Chat mit einer bekannten Nummer steht die Nummer an erster Stelle.',
  'Bu kanal şu an kullanılamıyor.' => 'Dieser Kanal ist derzeit nicht verfügbar.',
  'Site sohbeti' => 'Site-Chat',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => 'Alle Nachrichten von WhatsApp, Site-Chat und anderen Kanälen erscheinen hier live. Wählen Sie links einen Chat aus.',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => 'WhatsApp (Evolution API) Callcenter: Eingehende und ausgehende Nachrichten live sehen, neuen Chat starten, vorgefertigte Antworten, Tags, Aufgaben, interne Notizen, automatische Antworten; Registrierung von Spende (Flux Donate) und Zertifikat (Flux Certificates) über den Chat, Belegabgleich. Antwortvorschlag mit künstlicher Intelligenz und automatischer Spendenassistent mit OpenRouter.',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => 'WhatsApp (Evolution API) Callcenter: Eingehende und ausgehende Nachrichten live sehen, neuen Chat starten, vorgefertigte Antworten, Tags, Aufgaben, interne Notizen, automatische Antworten; Registrierung von Spende (Flux Donate) und Zertifikat (Flux Certificates) über den Chat, Belegabgleich. Antwortvorschlag mit künstlicher Intelligenz und automatischer Spendenassistent mit OpenRouter.',
  'Hide' => 'Ausblenden',
  'Show' => 'Anzeigen',
  'Deleted for everyone' => 'Für alle gelöscht',
  'Hidden in the panel' => 'Im Panel ausgeblendet',
  'Delete for everyone' => 'Für alle löschen',
  'Hide in the panel only' => 'Nur im Panel ausblenden',
  'WhatsApp doesn\'t allow deleting a received message for everyone; it stays on the contact\'s phone and is only hidden in the panel.' => 'WhatsApp erlaubt nicht, eine empfangene Nachricht für alle zu löschen; sie bleibt auf dem Telefon des Kontakts und wird nur im Panel ausgeblendet.',
  'Delete for everyone is turned off in the settings; the message is only hidden in the panel and stays on the contact\'s phone.' => 'Für alle löschen ist in den Einstellungen deaktiviert; die Nachricht wird nur im Panel ausgeblendet und bleibt auf dem Telefon des Kontakts.',
  'This channel doesn\'t support delete for everyone; the message is only hidden in the panel and stays on the contact\'s phone.' => 'Dieser Kanal unterstützt Für alle löschen nicht; die Nachricht wird nur im Panel ausgeblendet und bleibt auf dem Telefon des Kontakts.',
  'The time limit for delete for everyone has passed (WhatsApp allows about {h} hours after sending). The message stays on the contact\'s phone and is only hidden in the panel.' => 'Die Frist für Für alle löschen ist abgelaufen (WhatsApp erlaubt etwa {h} Stunden nach dem Senden). Die Nachricht bleibt auf dem Telefon des Kontakts und wird nur im Panel ausgeblendet.',
  'Only the sender or an administrator can delete this message for everyone; you can hide it in the panel.' => 'Nur der Absender oder ein Administrator kann diese Nachricht für alle löschen; Sie können sie im Panel ausblenden.',
  'If deleted for everyone, the message also turns into "This message was deleted" on the contact\'s phone. Time left: about {n} hours.' => 'Beim Löschen für alle wird die Nachricht auch auf dem Telefon des Kontakts zu „Diese Nachricht wurde gelöscht“. Verbleibende Zeit: etwa {n} Stunden.',
  'Deleted messages are kept on the server: the chat shows a "This message was deleted" line and the team can click it to see the content. AI does not read deleted messages.' => 'Gelöschte Nachrichten bleiben auf dem Server: Im Chat steht „Diese Nachricht wurde gelöscht“, das Team kann darauf klicken und den Inhalt sehen. Die KI liest gelöschte Nachrichten nicht.',
  'Message not found.' => 'Nachricht nicht gefunden.',
  'This message was already deleted.' => 'Diese Nachricht wurde bereits gelöscht.',
  'Only the sender or an administrator can delete this message for everyone.' => 'Nur der Absender oder ein Administrator kann diese Nachricht für alle löschen.',
  'This message can\'t be deleted for everyone on this channel. You can hide it in the panel instead.' => 'Diese Nachricht kann in diesem Kanal nicht für alle gelöscht werden. Sie können sie stattdessen im Panel ausblenden.',
  'The time limit for deleting for everyone has passed. You can hide it in the panel instead.' => 'Die Frist für Für alle löschen ist abgelaufen. Sie können die Nachricht stattdessen im Panel ausblenden.',
  'WhatsApp did not delete the message.' => 'WhatsApp hat die Nachricht nicht gelöscht.',
  'Delete for everyone time limit (hours)' => 'Frist für Für alle löschen (Stunden)',
  'WhatsApp lets you delete a sent message for everyone only for about 2 days and 12 hours (60 hours). After this limit, or for received messages, the message is only hidden in the panel: it stays on the contact\'s phone. 0 turns off delete for everyone. Deleted messages are never removed from the server; the team can still open them.' => 'WhatsApp erlaubt das Löschen einer gesendeten Nachricht für alle nur etwa 2 Tage und 12 Stunden (60 Stunden). Danach oder bei empfangenen Nachrichten wird die Nachricht nur im Panel ausgeblendet und bleibt auf dem Telefon des Kontakts. 0 deaktiviert Für alle löschen. Gelöschte Nachrichten werden nie vom Server entfernt; das Team kann sie weiterhin öffnen.',
  'Last update request %1$s. While the panel is open it checks for new messages every %2$d s (3 s while a reply is streaming, up to 15 s when nothing changes) and once a minute in a background tab.' => 'Letzte Aktualisierungsanforderung %1$s. Während das Panel geöffnet ist, prüft es alle %2$d s auf neue Nachrichten (3 s, während eine Antwort gestreamt wird, bis zu 15 s, wenn sich nichts ändert) und einmal pro Minute in einem Hintergrundtab.',
  'The open tab checks for new messages at this interval (10 recommended), every 3 s while a reply is streaming, and up to 15 s when nothing changes. A background tab checks once a minute. Errors back off up to 60 s.' => 'Der geöffnete Tab sucht in diesem Intervall nach neuen Nachrichten (10 empfohlen), alle 3 s während eine Antwort gestreamt wird und bis zu 15 s, wenn sich nichts ändert. Ein Hintergrundtab prüft einmal pro Minute. Bei Fehlern wird der Abstand auf bis zu 60 s gedehnt.',
  'Flux Donate is not active.' => 'Flux Donate ist nicht aktiv.',
  'Donor\'s earlier referral' => 'Frühere Empfehlung des Spenders',
  'Referral' => 'Empfehlung',
  'Order' => 'Bestellung',
  'Confirmation code' => 'Bestätigungscode',
  'Recorded from' => 'Erfasst über',
  'Entered by' => 'Erfasst von',
  'Items' => 'Positionen',
  'On behalf of: {n}' => 'Im Namen von: {n}',
  'Receipts' => 'Belege',
  'Revoked' => 'Widerrufen',
  '{n} paid gifts · {m}' => '{n} bezahlte Spenden · {m}',
  'No contact details.' => 'Keine Kontaktdaten.',
  'No referral.' => 'Keine Empfehlung.',
  'Has the payment reached the account? When you confirm, the certificate is made and sent to the donor.' => 'Ist die Zahlung auf dem Konto eingegangen? Nach der Bestätigung wird die Urkunde erstellt und an den Spender gesendet.',

 ),
);
